// ==================== 媒体转换功能 ====================

async function startMediaConvert() {
    if (currentMediaFileInfos.length === 0) {
        showToast('请先选择要转换的文件', 'error');
        return;
    }

    const outputPath = document.getElementById('media-output-path').value;
    const statusEl = document.getElementById('media-status');

    // 直接使用本地文件路径
    const uploadedPaths = currentMediaFileInfos
        .map(f => f.path)
        .filter(p => p);

    if (uploadedPaths.length === 0) {
        showToast('没有有效的文件路径', 'error');
        return;
    }

    // 设置 uploadedPath 供后续使用
    currentMediaFileInfos.forEach(f => { f.uploadedPath = f.path; });

    // 确定当前激活的子标签页
    const activeSubtab = document.querySelector('#media-panel .subtab-content.active');
    const subtabId = activeSubtab?.id || '';

    // 批量截图有自己的独立处理函数
    if (subtabId === 'media-thumbnail-subtab') {
        startBatchThumbnail();
        return;
    }

    // 画面分类有自己的独立处理函数
    if (subtabId === 'media-classify-subtab') {
        startImageClassify();
        return;
    }

    let payload = {
        files: uploadedPaths,
        output_dir: outputPath
    };

    // 根据子标签页构建请求参数
    if (subtabId === 'media-logo-subtab') {
        // Logo 叠加模式
        const logoPreset = document.querySelector('input[name="logo-preset"]:checked')?.value;

        if (logoPreset === 'custom') {
            // 自定义 Logo
            const customLogoPath = document.getElementById('custom-logo-file')?.dataset?.filePath;
            if (!customLogoPath) {
                showToast('请选择自定义 Logo 图片', 'error');
                return;
            }
            payload.mode = 'custom_logo';
            payload.custom_logo = {
                path: customLogoPath,
                x: parseInt(document.getElementById('logo-pos-x').value) || 590,
                y: parseInt(document.getElementById('logo-pos-y').value) || 1810,
                width: parseInt(document.getElementById('logo-width').value) || 400,
                height: parseInt(document.getElementById('logo-height').value) || 90
            };
        } else {
            payload.mode = logoPreset || 'hailuo';
            payload.logo_override = getLogoOverrideFromInputs();
        }

    } else if (subtabId === 'media-watermark-subtab') {
        // 文字水印模式
        payload.mode = 'watermark';

        const text = document.getElementById('watermark-text').value || 'AI Generated';
        const fontFamily = document.getElementById('watermark-font').value || 'Arial';
        const fontSize = parseInt(document.getElementById('watermark-fontsize').value) || 24;
        const color = document.getElementById('watermark-color').value || '#ffffff';
        const opacity = parseFloat(document.getElementById('watermark-opacity').value) || 1;
        const hasStroke = document.getElementById('watermark-stroke').checked;
        const strokeColor = document.getElementById('watermark-stroke-color').value || '#000000';
        const strokeWidth = parseInt(document.getElementById('watermark-stroke-width').value) || 2;
        const hasShadow = document.getElementById('watermark-shadow').checked;
        const position = document.getElementById('watermark-position').value || 'top-right';

        // 位置转换为 FFmpeg xy 表达式
        let posX = 'w-tw-10', posY = '10';
        switch (position) {
            case 'top-left': posX = '10'; posY = '10'; break;
            case 'top-right': posX = 'w-tw-10'; posY = '10'; break;
            case 'bottom-left': posX = '10'; posY = 'h-th-10'; break;
            case 'bottom-right': posX = 'w-tw-10'; posY = 'h-th-10'; break;
            case 'center': posX = '(w-tw)/2'; posY = '(h-th)/2'; break;
            case 'custom':
                posX = document.getElementById('watermark-pos-x').value || 'w-tw-10';
                posY = document.getElementById('watermark-pos-y').value || '10';
                break;
        }

        payload.watermark = {
            text: text,
            font: fontFamily,
            font_size: fontSize,
            color: color,
            opacity: opacity,
            stroke: hasStroke,
            stroke_color: strokeColor,
            stroke_width: strokeWidth,
            shadow: hasShadow,
            x: posX,
            y: posY
        };

    } else if (subtabId === 'media-format-subtab') {
        // 格式转换模式
        const formatMode = document.querySelector('input[name="format-mode"]:checked')?.value || 'h264';
        payload.mode = formatMode;

        if (formatMode === 'audio_split') {
            const exportMp3 = document.getElementById('export-split-mp3').checked;
            const exportMp4 = document.getElementById('export-split-mp4').checked;

            if (!exportMp3 && !exportMp4) {
                showToast('请至少选择一种导出格式', 'error');
                return;
            }

            const cutPointsMap = {};
            for (let i = 0; i < currentMediaFileInfos.length; i++) {
                const file = currentMediaFileInfos[i];
                const input = document.getElementById(`audio-cut-points-${i}`);
                const value = input ? input.value.trim() : '';

                // 允许不填写裁切点（直接转换整个文件）
                // 使用上传后的路径作为 key
                const serverPath = file.uploadedPath || file.path;
                if (value) {
                    cutPointsMap[serverPath] = value;
                    currentAudioCutPoints[file.path] = value;
                }
            }

            payload.cut_points_map = cutPointsMap;
            payload.export_mp3 = exportMp3;
            payload.export_mp4 = exportMp4;
        } else if (formatMode === 'audio_fx') {
            payload.reverbEnabled = document.getElementById('audio-fx-reverb-enabled')?.checked || false;
            payload.reverbPreset = document.getElementById('audio-fx-reverb-preset')?.value || 'hall';
            payload.reverbMix = parseFloat(document.getElementById('audio-fx-reverb-mix')?.value || '30');
            payload.stereoWidth = parseFloat(document.getElementById('audio-fx-stereo-width')?.value || '100');
            payload.outputFormat = document.getElementById('audio-fx-output-format')?.value || 'mp3';
        } else if (formatMode === 'txt_wrap') {
            payload.txt_wrap_width = parseInt(document.getElementById('txt-wrap-width')?.value || '18');
        }
    } else {
        // 默认：使用第一个子标签页的 Logo 模式
        payload.mode = document.querySelector('input[name="logo-preset"]:checked')?.value || 'hailuo';
    }

    try {
        updateStatus('开始转换...', 'processing', 'media-status');
        document.getElementById('media-progress').classList.remove('hidden');
        setIndeterminateProgress('media-progress', true);

        const response = await apiFetch(`${API_BASE}/media/convert`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });

        const result = await response.json();

        document.getElementById('media-progress').classList.add('hidden');
        setIndeterminateProgress('media-progress', false);

        if (response.ok) {
            updateStatus('转换完成！', 'success', 'media-status');
            showToast(result.message, 'success');

            // 显示下载链接（带时长信息）
            if (result.files && result.files.length > 0) {
                showConvertedFilesDownload(result.files, result.files_info);
            }
        } else {
            updateStatus('错误: ' + result.error, 'error', 'media-status');
            showToast('错误: ' + result.error, 'error');
        }
    } catch (error) {
        document.getElementById('media-progress').classList.add('hidden');
        setIndeterminateProgress('media-progress', false);
        updateStatus('请求失败', 'error', 'media-status');
        showToast('请求失败: ' + error.message, 'error');
    }
}

function showConvertedFilesDownload(files, filesInfo) {
    // 在状态区域下方显示下载链接
    const statusSection = document.querySelector('#media-panel .status-section');
    if (!statusSection) return;

    // 移除旧的下载区域
    const oldDownloadArea = document.getElementById('media-download-area');
    if (oldDownloadArea) oldDownloadArea.remove();

    const downloadArea = document.createElement('div');
    downloadArea.id = 'media-download-area';
    downloadArea.style.cssText = 'margin-top: 12px; padding: 12px; background: var(--bg-tertiary); border-radius: 8px;';

    // 标题行和下载全部按钮
    const header = document.createElement('div');
    header.style.cssText = 'display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px;';

    const title = document.createElement('div');
    title.style.cssText = 'font-weight: 500; color: var(--text-primary);';
    title.textContent = `✅ 已生成 ${files.length} 个文件:`;

    const downloadAllBtn = document.createElement('button');
    downloadAllBtn.className = 'btn btn-primary';
    downloadAllBtn.style.cssText = 'padding: 4px 12px; font-size: 12px;';
    downloadAllBtn.textContent = '📦 下载全部';
    downloadAllBtn.onclick = () => downloadAllFiles(files);

    header.appendChild(title);
    header.appendChild(downloadAllBtn);
    downloadArea.appendChild(header);

    const list = document.createElement('div');
    list.style.cssText = 'display: flex; flex-direction: column; gap: 4px; max-height: 150px; overflow-y: auto;';

    // 创建路径到时长的映射
    const durationMap = {};
    if (filesInfo) {
        filesInfo.forEach(info => {
            durationMap[info.path] = info.duration;
        });
    }

    files.forEach(filePath => {
        const filename = filePath.split('/').pop();
        // 去掉 UUID 前缀
        let displayName = filename;
        if (filename.includes('_') && filename.split('_')[0].length === 8) {
            displayName = filename.split('_').slice(1).join('_');
        }

        // 获取时长
        const duration = durationMap[filePath];
        const durationStr = duration ? ` (${formatDuration(duration)})` : '';

        const link = document.createElement('a');
        link.href = normalizeFilePath(filePath);
        link.textContent = `📥 ${displayName}${durationStr}`;
        link.style.cssText = 'color: var(--accent); text-decoration: none; font-size: 13px;';
        link.download = displayName;
        list.appendChild(link);
    });

    downloadArea.appendChild(list);
    statusSection.appendChild(downloadArea);
}

function formatDuration(seconds) {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    const ms = Math.round((seconds % 1) * 10);
    return `${mins}:${secs.toString().padStart(2, '0')}.${ms}`;
}

async function downloadAllFiles(files) {
    showToast('正在打包 ZIP...', 'info');

    try {
        const response = await apiFetch(`${API_BASE}/file/download-zip`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ files })
        });

        if (!response.ok) {
            throw new Error('打包失败');
        }

        // 获取 blob 并触发下载
        const blob = await response.blob();
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'converted_files.zip';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);

        showToast('ZIP 打包下载完成', 'success');
    } catch (error) {
        showToast('下载失败: ' + error.message, 'error');
    }
}

async function selectMediaOutputDir() {
    try {
        const dir = await window.electronAPI.selectDirectory();
        if (dir) {
            document.getElementById('media-output-path').value = dir;
        }
    } catch (error) {
        console.error('选择目录失败:', error);
        showToast('选择目录失败', 'error');
    }
}

// HTML 转义（含单/双引号），用于拼接进 innerHTML 和属性值的文本
function escapeHtmlAttr(v) {
    return String(v ?? '').replace(/[&<>"']/g, (m) => ({
        '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    }[m]));
}

// 重新进入媒体面板时，按当前侧边栏选中项恢复顶部通用文件选择区的显示状态
// （与 switchMediaSubtab 使用同一份“自带文件输入”的板块清单）
function syncMediaFileSectionVisibility() {
    const mediaFileSection = document.getElementById('media-file-section');
    if (!mediaFileSection) return;
    const activeItem = document.querySelector('.media-sidebar .sidebar-item.active');
    let subtabName = 'media-logo';
    if (activeItem) {
        if (activeItem.dataset.action === 'format') {
            subtabName = 'media-format';
        } else if (activeItem.dataset.action === 'subtab') {
            subtabName = activeItem.dataset.subtab;
        }
    }
    const tabsWithOwnInput = ['media-scene', 'media-smartkf', 'media-thumbnail', 'media-classify', 'media-visualreview', 'media-batchcut', 'media-autoedit', 'media-batchtxt', 'media-unirename', 'media-speechrename', 'media-namematching', 'media-batchrename', 'media-audiomatch', 'media-organizer', 'media-multiwindow'];
    mediaFileSection.style.display = tabsWithOwnInput.includes(subtabName) ? 'none' : '';
}

// 素材快速审核：只渲染当前片段组，避免一次加载数百条视频占满内存。
const visualReviewState = { sourceKind: 'local', sourceLinks: '', sourceLabel: '', sourceCacheToLocal:false, sourceDownloadDirectory:'', root: '', suites: [], suiteIndex: 0, current: 0, statuses: {}, feedback: {}, batchName: '', activePath: '', filter: 'all', mediaTypeFilter: 'all', fileNameQuery: '', view: 'review', numericSuffix: false, hoverRate: 2, hoverAudio: true, cardWidth: 210, previewStartTime: 0, suiteQuery: '', suiteNeedsReviewOnly: false, groupNeedsReviewOnly: false, newlyAddedPaths: [], groupingMode: 'name', groupSize: 6, preserveSelectedHierarchy: true, preserveRejectHierarchy: true };
const visualReviewTabs = [];
let visualReviewActiveTabId = '';
function visualReviewStateSnapshot() {
    return { sourceKind: visualReviewState.sourceKind || 'local', sourceLinks: visualReviewState.sourceLinks || '', sourceLabel: visualReviewState.sourceLabel || '', sourceCacheToLocal:visualReviewState.sourceCacheToLocal===true, sourceDownloadDirectory:visualReviewState.sourceDownloadDirectory||'', root: visualReviewState.root, suites: visualReviewState.suites, suiteIndex: visualReviewState.suiteIndex, current: visualReviewState.current, statuses: { ...(visualReviewState.statuses || {}) }, feedback: { ...(visualReviewState.feedback || {}) }, batchName: visualReviewState.batchName, activePath: visualReviewState.activePath, filter: visualReviewState.filter, mediaTypeFilter: visualReviewState.mediaTypeFilter || 'all', fileNameQuery: visualReviewState.fileNameQuery || '', view: visualReviewState.view, numericSuffix: visualReviewState.numericSuffix, hoverRate: visualReviewState.hoverRate, hoverAudio: visualReviewState.hoverAudio, groupHoverPreview: visualReviewState.groupHoverPreview !== false, cardWidth: visualReviewState.cardWidth, previewStartTime: Math.max(0, Number(visualReviewState.previewStartTime) || 0), suiteQuery: visualReviewState.suiteQuery, suiteNeedsReviewOnly: visualReviewState.suiteNeedsReviewOnly === true, groupNeedsReviewOnly: visualReviewState.groupNeedsReviewOnly === true, newlyAddedPaths: visualReviewState.newlyAddedPaths, groupingMode: visualReviewState.groupingMode || 'name', groupSize: visualReviewState.groupSize || 6, preserveSelectedHierarchy: visualReviewState.preserveSelectedHierarchy !== false, preserveRejectHierarchy: visualReviewState.preserveRejectHierarchy !== false };
}
function visualReviewSyncActiveTab() {
    const tab = visualReviewTabs.find(item => item.id === visualReviewActiveTabId);
    if (tab) tab.state = visualReviewStateSnapshot();
}
function visualReviewStartTab(rootPath) {
    visualReviewSyncActiveTab();
    const id = `review-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
    const state = { ...visualReviewStateSnapshot(), sourceKind:'local', sourceLinks:'', sourceLabel:'', sourceCacheToLocal:false, sourceDownloadDirectory:'', root: rootPath, suites: [], suiteIndex: 0, current: 0, statuses: {}, feedback: {}, batchName: '', activePath: '', view: 'review', previewStartTime: 0, suiteQuery: '', fileNameQuery: '', newlyAddedPaths: [], groupingMode: 'name' };
    visualReviewTabs.push({ id, label: String(rootPath || '').split(/[/\\]/).filter(Boolean).pop() || '新审核', state });
    visualReviewActiveTabId = id;
    Object.assign(visualReviewState, state);
}
function visualReviewActivateTab(id) {
    visualReviewSyncActiveTab();
    const tab = visualReviewTabs.find(item => item.id === id);
    if (!tab) return;
    visualReviewActiveTabId = id;
    Object.assign(visualReviewState, { ...tab.state, previewStartTime: Math.max(0, Number(tab.state?.previewStartTime) || 0), statuses: { ...(tab.state?.statuses || {}) }, feedback: { ...(tab.state?.feedback || {}) } });
    const numericSuffix = document.getElementById('visual-review-numeric-suffix');
    if (numericSuffix) numericSuffix.checked = !!visualReviewState.numericSuffix;
    visualReviewRender();
}
function visualReviewCloseTab(id) {
    const index = visualReviewTabs.findIndex(tab => tab.id === id);
    if (index < 0) return;
    const wasActive = visualReviewActiveTabId === id;
    visualReviewTabs.splice(index, 1);
    if (!wasActive) return visualReviewRender();
    const next = visualReviewTabs[index] || visualReviewTabs[index - 1];
    if (next) {
        visualReviewActiveTabId = next.id;
        Object.assign(visualReviewState, { ...next.state, previewStartTime: Math.max(0, Number(next.state?.previewStartTime) || 0) });
    } else {
        visualReviewActiveTabId = '';
        Object.assign(visualReviewState, { root: '', suites: [], suiteIndex: 0, current: 0, statuses: {}, feedback: {}, batchName: '', activePath: '', view: 'review', previewStartTime: 0, suiteQuery: '', fileNameQuery: '', suiteNeedsReviewOnly: false, groupNeedsReviewOnly: false, newlyAddedPaths: [], groupingMode: 'name' });
    }
    const numericSuffix = document.getElementById('visual-review-numeric-suffix');
    if (numericSuffix) numericSuffix.checked = !!visualReviewState.numericSuffix;
    visualReviewRender();
}
function visualReviewGroupKey(fileName) {
    const stem = String(fileName || '').replace(/\.[^.]+$/, '');
    const withoutCopySuffix = stem.replace(/(?:\s*[(（]\s*\d+\s*[)）])+\s*$/u, '').trim();
    // 只移除明确的版本标记；片段号和前面的名称都属于片段身份。
    const version = /(?:\s*[-_]v(?:ersion)?\s*\d+|\s*[-_]?副本\s*\d*)$/iu;
    const numeric = /(?:\s*[-_]\d+)$/u;
    return withoutCopySuffix.replace(visualReviewState.numericSuffix ? numeric : version, '').trim() || stem;
}

function visualReviewNamingHelp() {
    return `<div class="hint" style="flex-basis:100%;padding:8px 10px;border:1px solid var(--border-color);border-radius:6px;line-height:1.8;">
      <strong>同组候选的命名规则（按名字分组）：</strong><br>
      推荐把版本编号放在扩展名前：<code>片段1.mp4</code>、<code>片段1 (2).mp4</code>、<code>片段1（3）.mp4</code> 会归为同一组。英文 <code>(2)</code>、中文 <code>（2）</code> 及混用 <code>(2）</code>、<code>（2)</code> 都有效，不需要勾选数字尾缀。<br>
      未勾选数字尾缀时，还支持明确版本尾缀：<code>片段1-v2.mp4</code>、<code>片段1_v3.mp4</code>、<code>片段1副本2.mp4</code>。<br>
      “数字尾缀也视为版本”用于额外去掉 <code>-1</code>、<code>_2</code> 等纯数字尾缀；这可能合并不同片段，请仅在数字确实表示版本时使用。为避免歧义，多个候选统一使用括号编号。<code>片段1</code> 与 <code>片段2</code> 是不同组；不同套文件夹分别分组。
    </div>`;
}

function visualReviewIsImage(item) {
    return !item?.isDirectory && /\.(jpe?g|png|webp|gif|bmp|avif|svg)$/i.test(item?.name || '');
}
function visualReviewIsVideo(item) {
    return !item?.isDirectory && /\.(mp4|mov|mkv|avi|webm|m4v)$/i.test(item?.name || '');
}
function visualReviewIsSupportedMedia(item) {
    return visualReviewIsVideo(item) || visualReviewIsImage(item);
}
function visualReviewSuiteKey(item) {
    const parts = String(item?.relativePath || item?.name || '').split(/[/\\]/).filter(Boolean);
    // 总文件夹下的第一级文件夹就是一套；建议把每套素材放在各自的一级文件夹中。
    return parts.length > 1 ? parts[0] : '未分套';
}
function visualReviewFolderGroupKey(item, suiteKey) {
    const parts = String(item?.relativePath || item?.name || '').split(/[/\\]/).filter(Boolean);
    const relativeToSuite = suiteKey === '未分套' ? parts : parts.slice(1);
    const folders = relativeToSuite.slice(0, -1);
    return folders.length ? `文件夹：${folders.join('/')}` : '文件夹：套根目录';
}
function visualReviewBuildSuites(mediaList, groupingMode = visualReviewState.groupingMode || 'name') {
    const suiteMap = new Map();
    const settings = new Map((visualReviewState.suites || []).map(suite => [suite.key, suite]));
    mediaList.forEach(item => {
        const suiteKey = visualReviewSuiteKey(item);
        if (!suiteMap.has(suiteKey)) suiteMap.set(suiteKey, new Map());
        const groupMap = suiteMap.get(suiteKey);
        const suiteMode = settings.get(suiteKey)?.groupingMode || groupingMode;
        const key = suiteMode === 'individual' ? String(item.path || item.relativePath) : ['folder','count'].includes(suiteMode)
            ? visualReviewFolderGroupKey(item, suiteKey)
            : visualReviewGroupKey(item.name);
        if (!groupMap.has(key)) groupMap.set(key, []);
        const isImg = visualReviewIsImage(item);
        groupMap.get(key).push({
            ...(item.cloud ? {cloud:true,sourceUrl:item.sourceUrl,fileId:item.fileId,downloaded:item.downloaded===true,localPath:item.localPath||''} : {}),
            path: item.path,
            name: item.name,
            relativePath: item.relativePath || item.name,
            type: isImg ? 'image' : 'video'
        });
    });
    return [...suiteMap.entries()].map(([key, groupMap]) => ({
        key,
        groupingMode: settings.get(key)?.groupingMode || groupingMode,
        groupSize: Math.max(1, Math.min(100, Number(settings.get(key)?.groupSize || visualReviewState.groupSize) || 6)),
        collapsed: settings.get(key)?.collapsed === true,
        groups: [...groupMap.entries()].flatMap(([groupKey, files]) => {
            if ((settings.get(key)?.groupingMode || groupingMode) !== 'count') return [[groupKey,files]];
            const size = Math.max(1, Math.min(100, Math.floor(Number(settings.get(key)?.groupSize || visualReviewState.groupSize) || 6)));
            const ordered = files.slice().sort((a,b)=>a.relativePath.localeCompare(b.relativePath,undefined,{numeric:true}));
            return Array.from({length:Math.ceil(ordered.length/size)},(_,i)=>[`${groupKey} · 第${String(i+1).padStart(3,'0')}组`,ordered.slice(i*size,(i+1)*size)]);
        }).map(([groupKey, files]) => ({
            key: (settings.get(key)?.groupingMode || groupingMode) === 'individual' ? files[0].name : groupKey,
            files: files.sort((a, b) => a.relativePath.localeCompare(b.relativePath, undefined, { numeric: true }))
        })).sort((a, b) => a.key.localeCompare(b.key, undefined, { numeric: true }))
    })).sort((a, b) => a.key.localeCompare(b.key, undefined, { numeric: true }));
}

// 文件夹模式按实际目录归组，不再按文件名拆散。颜色只由名称决定，因此同名素材即使位于
// 不同文件夹，也会得到同一种细边框，方便在一个大文件夹中快速辨认。
function visualReviewNameSubgroups(files) {
    const groups = new Map();
    (files || []).forEach(file => {
        const key = visualReviewGroupKey(file.name);
        if (!groups.has(key)) groups.set(key, []);
        groups.get(key).push(file);
    });
    return [...groups.entries()].map(([key, groupFiles]) => ({
        key,
        files: groupFiles.sort((a, b) => a.relativePath.localeCompare(b.relativePath, undefined, { numeric: true })),
    })).sort((a, b) => a.key.localeCompare(b.key, undefined, { numeric: true }));
}

function visualReviewNameGroupColor(key) {
    const palette = ['#38bdf8', '#a78bfa', '#34d399', '#fbbf24', '#fb7185', '#22d3ee', '#f472b6', '#a3e635'];
    let hash = 0;
    for (const char of String(key || '')) hash = ((hash << 5) - hash + char.charCodeAt(0)) | 0;
    return palette[Math.abs(hash) % palette.length];
}
function visualReviewSetGroupingMode(mode) {
    const nextMode = ['name', 'folder', 'individual', 'count'].includes(mode) ? mode : 'name';
    if (nextMode === visualReviewState.groupingMode && visualReviewState.suites.every(suite => (suite.groupingMode || nextMode) === nextMode)) return;
    const files = visualReviewState.suites.flatMap(suite => suite.groups.flatMap(group => group.files));
    visualReviewState.groupingMode = nextMode;
    visualReviewState.suites.forEach(suite => { suite.groupingMode = nextMode; });
    visualReviewState.suites = visualReviewBuildSuites(files, nextMode);
    visualReviewState.suiteIndex = Math.min(visualReviewState.suiteIndex, Math.max(0, visualReviewState.suites.length - 1));
    visualReviewState.current = 0;
    visualReviewPersist();
    visualReviewRender();
}
function visualReviewSetSuiteGroupingMode(index, mode) {
    const suite = visualReviewState.suites[Number(index)];
    if (!suite) return;
    const nextMode = ['name', 'folder', 'individual', 'count'].includes(mode) ? mode : 'name';
    if ((suite.groupingMode || visualReviewState.groupingMode) === nextMode) return;
    const files = suite.groups.flatMap(group => group.files);
    suite.groupingMode = nextMode;
    const rebuilt = visualReviewBuildSuites(files, nextMode).find(item => item.key === suite.key);
    if (rebuilt) visualReviewState.suites[Number(index)] = rebuilt;
    if (visualReviewState.suiteIndex === Number(index)) visualReviewState.current = 0;
    visualReviewPersist();
    visualReviewRender();
}
function visualReviewSetGroupSize(value, index = null) {
    const size = Math.max(1,Math.min(100,Math.floor(Number(value)||6)));
    const files = visualReviewState.suites.flatMap(suite=>suite.groups.flatMap(group=>group.files));
    if (index == null) { visualReviewState.groupSize=size;visualReviewState.suites.forEach(suite=>{suite.groupSize=size;}); }
    else if (visualReviewState.suites[Number(index)]) visualReviewState.suites[Number(index)].groupSize=size;
    visualReviewState.suites=visualReviewBuildSuites(files);
    visualReviewState.current=0;visualReviewPersist();visualReviewRender();
}
function visualReviewSetSuiteCollapsed(index, collapsed) {
    const suite = visualReviewState.suites[Number(index)];
    if (!suite) return;
    suite.collapsed = Boolean(collapsed);
    visualReviewPersist();
    visualReviewRender();
}
function visualReviewSetAllSuitesCollapsed(collapsed) {
    visualReviewState.suites.forEach(suite => { suite.collapsed = Boolean(collapsed); });
    visualReviewPersist();
    visualReviewRender();
}
function visualReviewCurrentGroups() { return visualReviewState.suites[visualReviewState.suiteIndex]?.groups || []; }
function visualReviewIsSourceVideo(item) {
    return visualReviewIsSupportedMedia(item);
}

function visualReviewFormatGroupBadge(passCount, usableCount) {
    const total = passCount + usableCount;
    if (total === 0) {
        return {
            text: '已选 0 个',
            style: 'display:inline-flex;align-items:center;padding:1px 8px;border-radius:12px;font-size:12px;color:#94a3b8;background:rgba(148,163,184,0.12);border:1px solid rgba(148,163,184,0.25);'
        };
    }
    let detail = '';
    if (passCount > 0 && usableCount > 0) {
        detail = ` (${passCount}合格 · ${usableCount}勉强)`;
    } else if (passCount > 0) {
        detail = passCount > 1 ? ` (${passCount}合格)` : ' (合格)';
    } else {
        detail = usableCount > 1 ? ` (${usableCount}勉强)` : ' (勉强)';
    }
    const isPass = passCount > 0;
    const color = isPass ? '#4ade80' : '#facc15';
    const bg = isPass ? 'rgba(74,222,128,0.16)' : 'rgba(250,204,21,0.16)';
    const border = isPass ? 'rgba(74,222,128,0.35)' : 'rgba(250,204,21,0.35)';
    return {
        text: `已选 ${total} 个${detail}`,
        style: `display:inline-flex;align-items:center;padding:1px 8px;border-radius:12px;font-size:12px;font-weight:700;background:${bg};color:${color};border:1px solid ${border};`
    };
}

function visualReviewUpdateGroupBadges(filePath) {
    if (!filePath) return;
    visualReviewState.suites.forEach((suite, sIdx) => {
        let suiteChosen = 0;
        suite.groups.forEach((group, gIdx) => {
            const passCount = group.files.filter(f => visualReviewState.statuses[f.path] === 'pass').length;
            const usableCount = group.files.filter(f => visualReviewState.statuses[f.path] === 'usable').length;
            if (passCount > 0 || usableCount > 0) suiteChosen++;
            if (group.files.some(f => f.path === filePath)) {
                const badgeEl = document.querySelector(`[data-group-badge="${sIdx}-${gIdx}"]`);
                if (badgeEl) {
                    const badge = visualReviewFormatGroupBadge(passCount, usableCount);
                    badgeEl.textContent = badge.text;
                    badgeEl.style.cssText = badge.style;
                    badgeEl.closest('section')?.classList.toggle('vr-group-has-pass', passCount > 0);
                }
                const passBtn = document.querySelector(`[data-group-pass-btn="${sIdx}-${gIdx}"]`);
                const clearBtn = document.querySelector(`[data-group-clear-btn="${sIdx}-${gIdx}"]`);
                const allPassed = group.files.length > 0 && passCount === group.files.length;
                if (passBtn) {
                    if (allPassed) {
                        passBtn.style.background = 'rgba(34,197,94,0.2)';
                        passBtn.style.border = '1px solid #16a34a';
                        passBtn.style.color = '#86efac';
                        passBtn.setAttribute('onclick', `visualReviewPassGroup(${sIdx}, ${gIdx}, false)`);
                        passBtn.title = '点击取消本组全选合格';
                        passBtn.innerHTML = '✓ 全组已合格 (点击清除)';
                    } else {
                        passBtn.style.background = 'rgba(34,197,94,0.12)';
                        passBtn.style.border = '1px solid rgba(74,222,128,0.3)';
                        passBtn.style.color = '#4ade80';
                        passBtn.setAttribute('onclick', `visualReviewPassGroup(${sIdx}, ${gIdx}, true)`);
                        passBtn.title = '将本组所有素材一键标记为合格';
                        passBtn.innerHTML = '✅ 整组通过';
                    }
                }
                if (clearBtn) {
                    if (!allPassed && (passCount > 0 || usableCount > 0)) {
                        clearBtn.style.display = 'inline-flex';
                    } else {
                        clearBtn.style.display = 'none';
                    }
                }
            }
        });
        const suiteEl = document.querySelector(`[data-suite-chosen-count="${sIdx}"]`);
        if (suiteEl) suiteEl.textContent = `${suiteChosen} 组已有合格/勉强`;
        const unselectedEl = document.querySelector(`[data-suite-unselected-count="${sIdx}"]`);
        if (unselectedEl) unselectedEl.textContent = `筛选未合格：${suite.groups.length - suiteChosen} 组`;
    });
}

