function createAutoEditGenerationTable(records, options = {}) {
    const wrap = document.createElement('div');
    wrap.style.cssText = 'overflow:auto;max-height:60vh;border:1px solid #475569;border-radius:8px;margin:10px 0';
    const table = document.createElement('table');
    table.style.cssText = 'width:100%;min-width:1000px;border-collapse:collapse;table-layout:fixed;font-size:12px';
    const head = document.createElement('thead');
    const header = document.createElement('tr');
    const titles = ['图片名', '第二列（空）', '生成命名', '完整描述词'];
    const widths = ['20%', '6%', '24%', '50%'];
    if (options.showScript) { titles.push('分段文案（仅匹配用）'); widths[3] = '30%'; widths.push('20%'); }
    if (options.onCopy) { titles.push('复制'); widths[3] = '38%'; widths.push('12%'); }
    if (options.related) {
        titles.splice(4, 0, '视频预览', '问题');
        widths.splice(0, widths.length, '14%', '4%', '17%', '30%', '12%', '14%', '9%');
        table.style.minWidth = '1500px';
    }
    titles.forEach((title, i) => {
        const th = document.createElement('th'); th.textContent = title;
        th.style.cssText = `width:${widths[i]};padding:10px;text-align:left;position:sticky;top:0;z-index:1;background:#252a37;border-bottom:1px solid #475569;`;
        header.append(th);
    });
    head.append(header); table.append(head);
    const body = document.createElement('tbody');
    records.forEach(record => {
        const row = document.createElement('tr');
        const values = options.showScript ? [...record.columns, record.text] : record.columns;
        values.forEach((value, i) => {
            const td = document.createElement('td');
            td.style.cssText = 'padding:10px;vertical-align:top;border:1px solid #334155;white-space:pre-wrap;overflow-wrap:anywhere;';
            if (i === 3) {
                const description = document.createElement('div');
                description.style.cssText = 'white-space:pre-wrap;overflow-wrap:anywhere;max-height:240px;overflow:auto;line-height:1.6';
                description.textContent = value; td.append(description);
            } else td.textContent = value;
            row.append(td);
        });
        const related = options.related ? options.related(record) : [];
        if (options.related) {
            const videos = document.createElement('td'); videos.style.cssText = 'padding:10px;vertical-align:top;border:1px solid #334155';
            const sources = [...new Set(related.flatMap(item => window.AutoEditGeneration.recordVideoSources(record, item.task, item.issue)))];
            if (!sources.length) videos.textContent = '未定位到对应视频';
            sources.forEach(source => {
                const button = document.createElement('button'); button.className = 'ae-batch-review-thumb ae-generation-video-thumb';
                button.dataset.autoeditThumbSource = encodeURIComponent(source);
                button.style.cssText = 'width:96px;height:auto;aspect-ratio:9/16;margin-bottom:5px';
                button.title = '点击预览原视频'; button.textContent = '加载中';
                button.onclick = () => playAutoEditBatchReviewThumbnail(button);
                const name = document.createElement('div'); name.style.cssText = 'overflow-wrap:anywhere;font-size:11px;margin-bottom:10px';
                name.textContent = source.split(/[/\\]/).pop(); videos.append(button, name);
            });
            const problem = document.createElement('td'); problem.style.cssText = 'padding:10px;vertical-align:top;border:1px solid #334155;white-space:pre-wrap;overflow-wrap:anywhere';
            problem.textContent = related.map(item => {
                const feedback = window.AutoEditGeneration.issueFeedback(record, item.task, item.issue);
                return `${item.task.outputName || item.task.name}\n问题：${item.issue.label}\n\n应读文案：\n${feedback.expected}\n\n实际识别文案：\n${feedback.actual}\n\n缺少文案：\n${feedback.missing || '尚未明确检出缺少文案'}\n\n${feedback.note}`;
            }).join('\n\n');
            row.append(videos, problem);
        }
        if (options.onCopy) {
            const td = document.createElement('td'); td.style.cssText = 'padding:10px;vertical-align:top;border:1px solid #334155;';
            const button = document.createElement('button'); button.className = 'btn btn-secondary'; button.textContent = '复制此条';
            button.onclick = () => withCopyButtonFeedback(button, () => options.onCopy(record)); td.append(button);
            const sendImmediateBtn = document.createElement('button');
            sendImmediateBtn.className = 'btn btn-primary';
            sendImmediateBtn.style.cssText = 'margin-top:6px;background:#ea580c;border-color:#ea580c;color:#fff;font-weight:700;display:block;width:100%;';
            sendImmediateBtn.textContent = '🚀 发回生成端重跑';
            sendImmediateBtn.onclick = () => sendAutoEditGenerationRowsToHedra([record], { autoStart: true }, sendImmediateBtn);
            const sendMarkBtn = document.createElement('button');
            sendMarkBtn.className = 'btn btn-secondary';
            sendMarkBtn.style.cssText = 'margin-top:6px;display:block;width:100%;';
            sendMarkBtn.textContent = '⚠️ 发回标待重跑';
            sendMarkBtn.onclick = () => sendAutoEditGenerationRowsToHedra([record], { autoStart: false }, sendMarkBtn);
            td.append(sendImmediateBtn, sendMarkBtn);
            if (options.onReview) {
                [...new Set(related.map(item => item.task))].filter(task => task.result).forEach(task => {
                    const edit = document.createElement('button'); edit.className = 'btn btn-secondary'; edit.textContent = '审核处理';
                    edit.style.marginTop = '8px'; edit.title = '进入审核页调整裁切、字幕或试听确认';
                    edit.onclick = () => options.onReview(task, record, related.find(item => item.task === task)?.issue); td.append(edit);
                });
            }
            if (options.context) {
                const context = document.createElement('div'); context.className = 'hint'; context.style.cssText = 'margin-top:8px;white-space:pre-wrap;overflow-wrap:anywhere';
                context.textContent = options.context(record); td.append(context);
            }
            row.append(td);
        }
        body.append(row);
    });
    table.append(body); wrap.append(table); return wrap;
}
const AUTOEDIT_GENERATION_PREVIEW_LIMIT = 80;
function renderAutoEditGenerationImport(showAll = false) {
    const preview = document.getElementById('autoedit-generation-preview');
    const input = document.getElementById('autoedit-generation-table');
    if (!preview || !input) return;
    preview.replaceChildren();
    if (!input.value.trim()) { preview.textContent = '在这里粘贴表格资料（⌘V / Ctrl+V）'; return; }
    try {
        const records = window.AutoEditGeneration.parseTable(input.value);
        const count = document.createElement('p');
        count.className = 'hint';
        count.textContent = `已载入 ${records.length} 条资料；第五列仅用于匹配，不会复制到最终结果。描述词可在单元格内滚动查看。`;
        preview.append(count);
        const outerDetails = preview.parentElement?.closest?.('details');
        if (outerDetails && !outerDetails.open) {
            if (!outerDetails._generationToggleBound) {
                outerDetails._generationToggleBound = true;
                outerDetails.addEventListener('toggle', () => {
                    if (outerDetails.open && outerDetails._generationNeedsRender) {
                        outerDetails._generationNeedsRender = false;
                        renderAutoEditGenerationImport(false);
                    }
                });
            }
            outerDetails._generationNeedsRender = true;
            return;
        }
        if (outerDetails) outerDetails._generationNeedsRender = false;
        const shouldTruncate = !showAll && records.length > AUTOEDIT_GENERATION_PREVIEW_LIMIT;
        const visibleRecords = shouldTruncate ? records.slice(0, AUTOEDIT_GENERATION_PREVIEW_LIMIT) : records;
        preview.append(createAutoEditGenerationTable(visibleRecords, { showScript: true }));
        if (shouldTruncate) {
            const moreBtn = document.createElement('button');
            moreBtn.type = 'button';
            moreBtn.className = 'btn btn-secondary';
            moreBtn.style.marginTop = '6px';
            moreBtn.textContent = `展开全部 ${records.length} 条资料（当前仅预览前 ${AUTOEDIT_GENERATION_PREVIEW_LIMIT} 条以保持流畅）`;
            moreBtn.onclick = () => renderAutoEditGenerationImport(true);
            preview.append(moreBtn);
        }
    } catch (error) { preview.textContent = error.message; }
}
function pasteAutoEditGenerationTable(event) {
    const text = event.clipboardData?.getData('text/plain');
    if (!text) return;
    event.preventDefault();
    document.getElementById('autoedit-generation-table').value = text;
    renderAutoEditGenerationImport(); saveAutoEditWorkspaceState();
}
window.renderAutoEditGenerationImport = renderAutoEditGenerationImport;
window.pasteAutoEditGenerationTable = pasteAutoEditGenerationTable;

async function copyAutoEditGenerationRows(records) {
    const table = window.AutoEditGeneration.exportTable(records);
    if (!table.count) { showToast('没有已匹配的生成资料，请先确认候选', 'warning'); return false; }
    try {
        let copied = false;
        if (navigator.clipboard?.write && typeof ClipboardItem !== 'undefined') {
            try {
                await navigator.clipboard.write([new ClipboardItem({
                    'text/plain': new Blob([table.text], { type: 'text/plain' }),
                    'text/html': new Blob([table.html], { type: 'text/html' })
                })]);
                copied = true;
            } catch (_) {}
        }
        if (!copied) {
            if (window.electronAPI?.writeClipboardText) await window.electronAPI.writeClipboardText(table.text);
            else await navigator.clipboard.writeText(table.text);
        }
        showToast(`已复制 ${table.count} 条生成资料（仅前四列）`, 'success');
        return true;
    } catch (error) { showToast(`复制失败：${error.message}`, 'error'); return false; }
}
async function copyAutoEditSegmentGenerationData(reviewIndex, batchTaskIndex = null, source = '') {
    const api = window.AutoEditGeneration;
    if (!api) { showToast('生成资料模块未加载', 'warning'); return false; }
    const task = batchTaskIndex !== null ? autoEditBatchTasks[batchTaskIndex] : autoEditReviewOwnerTask;
    if (batchTaskIndex !== null && !task) { showToast('当前任务已变化，请重新打开审核', 'warning'); return false; }
    const result = task && batchTaskIndex !== null ? getAutoEditBatchLiveResult(task) : autoEditLastResult;
    const segment = source ? result?.segments?.find(item => item.source === source) : result?.segments?.[reviewIndex];
    if (!segment) { showToast('当前片段已变化，请重新打开审核', 'warning'); return false; }
    return copyAutoEditGenerationForIssue({ kind: 'segment', source: segment.source,
        text: segment.script || '', recognized: segment.recognized_text || '',
        startLine: segment.script_start_line, endLine: segment.script_end_line }, task, result);
}
window.copyAutoEditSegmentGenerationData = copyAutoEditSegmentGenerationData;

let _cachedHedraFallbackTableAt = 0;
let _cachedHedraFallbackValid = false;
let _cachedHedraFallbackTableText = '';
let _cachedHedraFallbackRows = [];
let _cachedHedraFallbackStatusByKey = new Map();
let _cachedHedraLatestBatchMeta = { path: '', mtimeMs: -1, size: -1, tableText: '' };

function invalidateHedraFallbackSnapshotCache() {
    _cachedHedraFallbackValid = false;
    _cachedHedraFallbackTableAt = 0;
}

function getHedraFallbackSnapshot() {
    const nowMs = Date.now();
    if (_cachedHedraFallbackValid && nowMs - _cachedHedraFallbackTableAt < 10000) {
        return {
            tableText: _cachedHedraFallbackTableText,
            rawRows: _cachedHedraFallbackRows,
            statusByKey: _cachedHedraFallbackStatusByKey,
        };
    }
    _cachedHedraFallbackTableAt = nowMs;
    _cachedHedraFallbackValid = true;
    const parts = [];
    let rawRows = [];
    try {
        const dir = typeof getHedraBridgeDir === 'function' ? getHedraBridgeDir() : '';
        if (dir && window.electronAPI?.readFileText && window.electronAPI?.pathJoin) {
            const latestPath = window.electronAPI.pathJoin(dir, 'hedra-latest-batch.json');
            const st = typeof window.electronAPI.fsStat === 'function' ? window.electronAPI.fsStat(latestPath) : undefined;
            if (st === null) {
                _cachedHedraLatestBatchMeta = { path: latestPath, mtimeMs: -1, size: -1, tableText: '' };
            } else if (st && _cachedHedraLatestBatchMeta.path === latestPath && _cachedHedraLatestBatchMeta.mtimeMs === st.mtimeMs && _cachedHedraLatestBatchMeta.size === st.size) {
                if (_cachedHedraLatestBatchMeta.tableText) parts.push(_cachedHedraLatestBatchMeta.tableText);
            } else {
                const latestRaw = window.electronAPI.readFileText(latestPath);
                let tableText = '';
                if (latestRaw) {
                    const parsed = JSON.parse(latestRaw);
                    if (parsed?.generationTableText && String(parsed.generationTableText).trim()) {
                        tableText = String(parsed.generationTableText).trim();
                    }
                }
                if (st) _cachedHedraLatestBatchMeta = { path: latestPath, mtimeMs: st.mtimeMs, size: st.size, tableText };
                if (tableText) parts.push(tableText);
            }
        }
    } catch (_) {}
    try {
        if (typeof readLocalHedraFlowPoolState === 'function') {
            const localState = readLocalHedraFlowPoolState();
            if (!parts.length && localState?.payload?.generationTableText && String(localState.payload.generationTableText).trim()) {
                parts.push(String(localState.payload.generationTableText).trim());
            }
            if (Array.isArray(localState?.rawRows)) {
                rawRows = localState.rawRows;
            }
        }
    } catch (_) {}
    const cleanKey = s => String(s || '').split(/[/\\]/).pop().replace(/\.(mp4|mov|mkv|webm|avi|m4v)$/i, '').replace(/(?:\s+[(（]\s*\d+\s*[)）]|[_-]v\d+|[_-]副本\d*)+$/gi, '').normalize('NFKC').toLowerCase().replace(/[^\p{L}\p{N}]/gu, '');
    const statusByKey = new Map();
    for (const r of rawRows) {
        const k = cleanKey(r?.groupName);
        if (k && !statusByKey.has(k)) statusByKey.set(k, r);
    }
    _cachedHedraFallbackTableText = parts.join('\n').trim();
    _cachedHedraFallbackRows = rawRows;
    _cachedHedraFallbackStatusByKey = statusByKey;
    return {
        tableText: _cachedHedraFallbackTableText,
        rawRows: _cachedHedraFallbackRows,
        statusByKey: _cachedHedraFallbackStatusByKey,
    };
}

function getEffectiveAutoEditGenerationTableRaw(result = null, ownerTask = null) {
    const inputEl = document.getElementById('autoedit-generation-table');
    const isForeignTask = Boolean(ownerTask && typeof autoEditBatchTasks !== 'undefined' && Array.isArray(autoEditBatchTasks)
        && autoEditBatchTasks.length > 0 && !autoEditBatchTasks.includes(ownerTask)
        && (typeof autoEditReviewOwnerTask === 'undefined' || autoEditReviewOwnerTask !== ownerTask));
    const taskVal = String(ownerTask?.hedraGenerationTable || '').trim();
    const domVal = isForeignTask ? '' : String(inputEl?.value || '').trim();
    const resVal = String(result?.generation_table || ownerTask?.result?.generation_table || '').trim();
    if (domVal) return domVal;
    if (taskVal) return taskVal;
    if (resVal) return resVal;
    return String(getHedraFallbackSnapshot().tableText || '').trim();
}

function inferMissingClipNamesForBlock(block, segments = [], previousSegment = null, nextSegment = null, ownerTask = null) {
    const allSources = [
        ...(Array.isArray(segments) ? segments.map(s => s?.source) : []),
        ...(Array.isArray(ownerTask?.clips) ? ownerTask.clips.map(c => typeof c === 'string' ? c : c?.path || c?.name) : []),
    ].filter(Boolean);

    const parseClipStem = src => {
        const base = String(src || '').split(/[/\\]/).pop().replace(/\.(mp4|mov|mkv|webm|avi|m4v)$/i, '');
        const clean = base.replace(/(?:\s+[(（]\s*\d+\s*[)）]|[_-]v\d+|[_-]副本\d*)+$/gi, '').trim();
        const m = clean.match(/^(.*?)[-_]片段\s*(\d+)(?:[(（](\d+)[)）])?$/i);
        if (!m) return { clean, suitePrefix: '', segNum: null };
        return {
            clean,
            suitePrefix: String(m[1] || '').trim(),
            segNum: Number(m[2]) || null,
        };
    };

    let suitePrefix = '';
    const existingSegNums = new Set();
    for (const src of allSources) {
        const info = parseClipStem(src);
        if (info.suitePrefix && !suitePrefix) suitePrefix = info.suitePrefix;
        if (info.segNum) existingSegNums.add(info.segNum);
    }
    if (!suitePrefix) {
        const rawTaskName = String(ownerTask?.outputName || ownerTask?.name || '').trim().replace(/\.(mp4|mov|mkv|webm)$/i, '');
        if (rawTaskName && rawTaskName !== '未命名任务') suitePrefix = rawTaskName;
    }

    const prevInfo = previousSegment?.source ? parseClipStem(previousSegment.source) : { segNum: null };
    const nextInfo = nextSegment?.source ? parseClipStem(nextSegment.source) : { segNum: null };
    const prevSegNum = prevInfo.segNum;
    const nextSegNum = nextInfo.segNum;

    const missingSegNums = [];
    if (!prevSegNum && nextSegNum && nextSegNum > 1) {
        for (let n = 1; n < nextSegNum; n++) {
            if (!existingSegNums.has(n)) missingSegNums.push(n);
        }
        if (!missingSegNums.length) missingSegNums.push(nextSegNum - 1);
    } else if (prevSegNum && nextSegNum && nextSegNum - prevSegNum > 1) {
        for (let n = prevSegNum + 1; n < nextSegNum; n++) {
            if (!existingSegNums.has(n)) missingSegNums.push(n);
        }
        if (!missingSegNums.length) missingSegNums.push(prevSegNum + 1);
    } else if (prevSegNum && !nextSegNum) {
        if (!existingSegNums.has(prevSegNum + 1)) missingSegNums.push(prevSegNum + 1);
    }

    const inferredMissingNames = suitePrefix
        ? missingSegNums.map(n => `${suitePrefix}-片段${n}`)
        : [];

    return {
        suitePrefix,
        inferredMissingNames,
        missingSegNums,
        prevSegNum,
        nextSegNum,
        existingSegNums: [...existingSegNums].sort((a, b) => a - b),
    };
}

async function copyAutoEditMissingGenerationData(button) {
    const card = button?.closest('.autoedit-missing-placeholder');
    if (!card || !autoEditLastResult) return false;
    let inferredMissingNames = [];
    try {
        if (card.dataset.inferredMissingNames) {
            inferredMissingNames = JSON.parse(decodeURIComponent(card.dataset.inferredMissingNames));
        }
    } catch (_) {}
    return copyAutoEditGenerationForIssue({
        kind: 'missing',
        source: '',
        text: decodeURIComponent(card.dataset.missingText || ''),
        startLine: Number(card.dataset.scriptStartLine),
        endLine: Number(card.dataset.scriptEndLine),
        inferredMissingNames,
    }, autoEditReviewOwnerTask, autoEditLastResult);
}
window.copyAutoEditMissingGenerationData = copyAutoEditMissingGenerationData;

async function copyAutoEditGenerationForIssue(issue, task, result) {
    const api = window.AutoEditGeneration;
    if (!api) { showToast('生成资料模块未加载', 'warning'); return false; }
    const raw = getEffectiveAutoEditGenerationTableRaw(result, task);
    if (!raw.trim()) { showToast('请先导入或从生成端拉取生成资料表格', 'warning'); return false; }
    let records;
    try { records = api.parseTable(raw); }
    catch (error) { showToast(`生成资料表格格式有误：${error.message}`, 'warning'); return false; }
    const owner = task || { result, script: result?.script_text || '', clips: result?.clips || (result?.segments || []).map(item => item.source) };
    const byName = issue.kind === 'segment'
        ? api.matchReviewGroup({ groupName: issue.source, suite: owner.outputName || owner.name || '' }, records)
        : { selected: [], ambiguous: false };
    const match = byName.selected.length ? byName : api.matchIssue(issue, owner, records);
    if (!match.selected.length) {
        showToast(match.ambiguous || byName.ambiguous ? '当前文案匹配到多份生成资料，请在“查看资料匹配”中确认' : '未找到对应的生成资料', 'warning');
        return false;
    }
    return copyAutoEditGenerationRows(match.selected);
}

function openAutoEditGenerationReview(task, record, issue) {
    const index = autoEditBatchTasks.indexOf(task);
    const sources = window.AutoEditGeneration.recordVideoSources(record, task, issue);
    document.getElementById('autoedit-generation-matches')?.remove();
    if (index >= 0) openAutoEditBatchReview(index);
    else if (task.result) renderAutoEditResult(task.result);
    requestAnimationFrame(() => {
        const row = sources.length ? Array.from(document.querySelectorAll('.autoedit-review-row')).find(row => {
            const source = getAutoEditReviewRowSource(row);
            return sources.includes(source);
        }) : null;
        (row || document.getElementById('autoedit-result-section'))?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    });
}
async function copyAutoEditMatchedProblemGenerationData() {
    if (document.querySelector('.autoedit-review-row')) persistAutoEditBatchReview();
    let records;
    try { records = window.AutoEditGeneration.parseTable(getEffectiveAutoEditGenerationTableRaw(autoEditLastResult, autoEditReviewOwnerTask)); }
    catch (error) { showToast(error.message, 'error'); return false; }
    if (!records.length) { showToast('请先粘贴生成资料表格', 'warning'); return false; }
    const batch = document.getElementById('autoedit-batch-panel')?.style.display !== 'none';
    const tasks = batch ? autoEditBatchTasks.filter(autoEditBatchTaskHasIssues).map(task => ({...task, result:getAutoEditBatchLiveResult(task)}))
        : [{script:document.getElementById('autoedit-script')?.value || '', clips:autoEditFiles, result:autoEditLastResult}];
    if (batch) tasks.push(...window.AutoEditGeneration.unassignedScripts(autoEditBatchTasks, autoEditBatchScriptCells, autoEditBatchUnmatchedScripts)
        .filter(item => String(item.script || '').trim()).map(item => ({script:item.script, clips:[], result:null})));
    const matches = tasks.flatMap(task => window.AutoEditGeneration.collectIssues(task).map(issue => window.AutoEditGeneration.matchIssue(issue, task, records)));
    const selected = matches.flatMap(match => match.selected);
    if (!selected.length) { showToast('没有可靠匹配的资料，请点击“查看／调整资料匹配”确认候选', 'warning'); return false; }
    const copied = await copyAutoEditGenerationRows(selected);
    const unresolved = matches.filter(match => !match.selected.length).length;
    if (copied && unresolved) showToast(`已复制可靠匹配资料；另有 ${unresolved} 处未匹配或待确认，未加入复制`, 'info');
    return copied;
}
window.copyAutoEditMatchedProblemGenerationData = copyAutoEditMatchedProblemGenerationData;

// ==================== Hedra Flow 批量 <-> VideoKit 文案自动剪辑 双向联动（开发版/打包版双通道） ====================
const HEDRA_BRIDGE_PORTS = [18189, 18191, 18192, 18193];
const hedraHandledPushIds = new Set();
const hedraHandledClipEventIds = new Set();
const hedraPendingClipRefreshQueue = new Map();

function getHedraBridgeDir() {
    try {
        const autoSavePath = window.electronAPI?.legacyAutoSavePath;
        if (autoSavePath && window.electronAPI?.pathDirname && window.electronAPI?.pathJoin) {
            return window.electronAPI.pathJoin(window.electronAPI.pathDirname(autoSavePath), 'hedra-bridge');
        }
    } catch (_) {}
    return '';
}

function getCandidateHedraPorts() {
    const ports = [...HEDRA_BRIDGE_PORTS];
    try {
        const dir = getHedraBridgeDir();
        if (dir && window.electronAPI?.readFileText && window.electronAPI?.pathJoin) {
            const raw = window.electronAPI.readFileText(window.electronAPI.pathJoin(dir, 'hedra-server.json'));
            if (raw) {
                const info = JSON.parse(raw);
                if (Number(info?.port) && !ports.includes(Number(info.port))) {
                    ports.unshift(Number(info.port));
                }
            }
        }
    } catch (_) {}
    return ports;
}

async function fetchHedraBridgeOnPort(port, pathname, options = {}) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), options.timeoutMs || 2200);
    try {
        const resp = await fetch(`http://127.0.0.1:${port}${pathname}`, {
            method: options.method || 'GET',
            headers: options.body ? { 'Content-Type': 'application/json' } : undefined,
            body: options.body ? JSON.stringify(options.body) : undefined,
            signal: controller.signal,
        });
        clearTimeout(timer);
        if (resp.ok) {
            const data = await resp.json();
            return { ...data, _port: port };
        }
    } catch (_) {
        clearTimeout(timer);
    }
    return null;
}

async function fetchAllHedraBridges(pathname, options = {}) {
    const ports = getCandidateHedraPorts();
    const results = await Promise.all(ports.map(port => fetchHedraBridgeOnPort(port, pathname, options)));
    return results.filter(Boolean);
}

async function fetchHedraBridge(pathname, options = {}) {
    const all = await fetchAllHedraBridges(pathname, options);
    if (!all.length) return null;
    // 若同时开启了多个 Hedra 实例，优先选择有任务行的实例
    const withRows = all.find(r => Number(r?.rowCount) > 0 || Number(r?.payload?.rowCount) > 0 || (Array.isArray(r?.payload?.folders) && r.payload.folders.length > 0));
    return withRows || all[0];
}

async function sendAutoEditGenerationRowsToHedra(records, { autoStart = false } = {}, triggerBtn = null) {
    const normalized = (Array.isArray(records) ? records : []).map(r => {
        if (Array.isArray(r?.columns) && r.columns.length >= 4) return r;
        if (!r || !(r.groupName || r.prompt || r.spokenScript)) return null;
        return {...r, columns: [String(r.imageName || r.suiteName || '').trim(), '',
            String(r.groupName || '').trim(), String(r.prompt || r.spokenScript || '').trim()]};
    }).filter(Boolean);
    const unique = window.AutoEditGeneration.dedupeRecords(normalized);
    const rows = unique.map(r => ({
        imageName: String(r.columns[0] || '').trim(),
        groupName: String(r.columns[2] || '').trim().replace(/\.(mp4|mov|mkv|webm)$/i, ''),
        prompt: String(r.columns[3] || '').trim(),
        spokenScript: String(r.spokenScript || r.text || '').trim() || undefined,
        suiteName: r.suiteName || undefined,
        keepExistingPrompt: Boolean(r.keepExistingPrompt),
        hedraOrigin: r.hedraOrigin,
    })).filter(r => r.prompt || r.groupName || r.spokenScript);
    if (!rows.length) { showToast('没有可发回生成端的生成资料，请先确认匹配结果', 'warning'); return false; }
    try {
        const table = window.AutoEditGeneration.exportTable(unique);
        if (table?.text) {
            if (window.electronAPI?.writeClipboardText) await window.electronAPI.writeClipboardText(table.text);
            else await navigator.clipboard.writeText(table.text);
        }
    } catch (_) {}
    const originalText = triggerBtn?.dataset.hedraOriginalText || triggerBtn?.textContent || '';
    if (triggerBtn) { triggerBtn.dataset.hedraOriginalText = originalText; triggerBtn.disabled = true; triggerBtn.textContent = '⏳ 核对原始任务…'; }
    let acceptedCount = 0, queuedCount = 0, startedCount = 0, failedCount = 0;
    const issues = [];
    const destinations = [];
    try {
        // Probe capability first: old endpoints ignored dryRun and would mutate the active tab.
        let statuses = [];
        try { statuses = await fetchAllHedraBridges('/status', {timeoutMs: 1800}); } catch (_) {}
        const online = statuses.filter(s => s?.ok && Number(s.problemRowsProtocol) >= 2 && s.sourceId);
        const probes = await Promise.all(online.map(async status => {
            try {
                const result = await fetchHedraBridgeOnPort(status._port, '/mark-problem-rows', {
                    method: 'POST', timeoutMs: 5000, body: {rows, dryRun: true, appendUnmatched: false, focusWindow: false},
                });
                return {status, result};
            } catch (_) { return {status, result: null}; }
        }));
        const groups = new Map();
        rows.forEach((row, index) => {
            const candidates = new Map();
            for (const {status, result} of probes) {
                for (const match of (result?.ok ? result.matches || [] : [])) {
                    if (match.requestIndex !== index || !match.hedraOrigin?.sourceId || !match.hedraOrigin?.tabId || !match.hedraOrigin?.rowId) continue;
                    const origin = match.hedraOrigin;
                    candidates.set(JSON.stringify([origin.sourceId, origin.tabId, origin.rowId]), {status, origin});
                }
            }
            let target;
            if (!row.hedraOrigin && probes.some(p => p.result?.unresolved?.some(issue => issue.requestIndex === index && issue.reason === 'ambiguous'))) {
                failedCount++; issues.push('多个原任务同名，未回传'); return;
            }
            if (candidates.size === 1) target = [...candidates.values()][0];
            else if (candidates.size > 1) { failedCount++; issues.push('同名任务有多个来源，未回传'); return; }
            else {
                const origin = row.hedraOrigin;
                const ownerOnline = online.some(s => s.sourceId === origin?.sourceId);
                if (origin?.sourceId && origin.tabId && origin.rowId && !ownerOnline) {
                    // Offline queueing is allowed only with an exact original source address.
                    target = {status: null, origin};
                } else {
                    failedCount++;
                    const reasons = probes.flatMap(p => p.result?.unresolved || []).filter(p => p.requestIndex === index).map(p => p.reason);
                    issues.push(reasons.includes('ambiguous') ? '原批次内有同名冲突，未回传'
                        : reasons.includes('missing-original-tab') || reasons.includes('missing-original-row') ? '原标签页或原任务已不存在'
                        : statuses.length && !online.length ? '生成端同步服务需要重启以加载升级'
                        : ownerOnline ? '原任务核对未通过，请重试' : '未找到对应原任务，请确认生成端已打开原批次');
                    return;
                }
            }
            const key = target.origin.sourceId;
            if (!groups.has(key)) groups.set(key, {sourceId: key, status: target.status, rows: []});
            groups.get(key).rows.push({...row, hedraOrigin: target.origin});
        });
        const baseId = `vk_problem_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
        let groupIndex = 0;
        for (const group of groups.values()) {
            const payload = {id: `${baseId}_${groupIndex++}`, timestamp: Date.now(), rows: group.rows,
                targetSourceId: group.sourceId, autoStart: Boolean(autoStart), appendUnmatched: false, source: 'videokit-autoedit'};
            let queued = false;
            try {
                const api = window.electronAPI;
                const dir = getHedraBridgeDir();
                if (dir && api?.ensureDirectory && api?.writeFileText && api?.pathJoin) {
                    await api.ensureDirectory(dir);
                    queued = await api.writeFileText(api.pathJoin(dir, `pending-to-hedra-${payload.id}.json`), JSON.stringify(payload, null, 2)) !== false;
                }
            } catch (_) {}
            let reply = null;
            if (group.status) {
                try { reply = await fetchHedraBridgeOnPort(group.status._port, '/mark-problem-rows', {method: 'POST', body: payload, timeoutMs: 12000}); } catch (_) {}
            }
            if (reply?.ok) {
                const matched = Number(reply.matchedCount) || 0;
                acceptedCount += matched;
                startedCount += Number(reply.startedCount) || 0;
                failedCount += group.rows.length - matched;
                for (const m of reply.matches || []) if (m.hedraOrigin?.tabName) destinations.push(m.hedraOrigin.tabName);
                if (reply.busyCount) issues.push(`${reply.busyCount} 个原任务正在生成，未修改`);
                if (reply.startErrors?.length) issues.push('部分任务已标记，但启动失败：' + reply.startErrors.map(e => e.error).join('；'));
                if (group.rows.length > matched && !reply.busyCount) issues.push('部分原任务已变化，未回传');
            } else if (queued) queuedCount += group.rows.length;
            else { failedCount += group.rows.length; issues.push('回传连接失败且本地队列写入失败'); }
        }
        const detail = [...new Set(issues)].join('；');
        const tabs = [...new Set(destinations)].join('、');
        const message = [acceptedCount ? `已回到原标签页${tabs ? `「${tabs}」` : ''}的 ${acceptedCount} 个原任务${autoStart ? `，已启动 ${startedCount} 个重跑` : '，已标记待重跑'}` : '',
            queuedCount ? `${queuedCount} 个已按原来源排队，等待生成端接收` : '',
            failedCount ? `${failedCount} 个未回传` : '', detail].filter(Boolean).join('；');
        if (triggerBtn) {
            triggerBtn.textContent = failedCount ? '⚠️ 部分未回传 · 重试' : queuedCount ? '⏳ 等待接收 · 再次发送' : issues.length ? '⚠️ 已标记 · 检查启动结果' : acceptedCount ? '✅ 已回到原任务 · 再次发送' : '❌ 发送失败 · 重试';
            triggerBtn.title = message;
        }
        showToast(message || '没有找到可回传的原任务', failedCount || issues.length ? 'warning' : acceptedCount ? 'success' : 'info', 8000);
        return acceptedCount + queuedCount > 0;
    } catch (error) {
        if (triggerBtn) { triggerBtn.textContent = '❌ 发送失败 · 重试'; triggerBtn.title = error?.message || String(error); }
        showToast(`发回生成端失败：${error?.message || error}`, 'error');
        return false;
    } finally {
        if (typeof invalidateHedraFallbackSnapshotCache === 'function') invalidateHedraFallbackSnapshotCache();
        if (triggerBtn) triggerBtn.disabled = false;
    }
}
window.sendAutoEditGenerationRowsToHedra = sendAutoEditGenerationRowsToHedra;

async function sendAutoEditMatchedProblemGenerationToHedra({ autoStart = false } = {}, triggerBtn = null) {
    if (document.querySelector('.autoedit-review-row')) persistAutoEditBatchReview();
    const raw = getEffectiveAutoEditGenerationTableRaw(autoEditLastResult, autoEditReviewOwnerTask);
    let records = [];
    if (raw.trim()) {
        try { records = window.AutoEditGeneration.parseTable(raw); }
        catch (error) { showToast(error.message, 'error'); return false; }
    }
    if (!records.length) { showToast('请先粘贴或从生成端拉取生成资料表格', 'warning'); return false; }
    const batch = document.getElementById('autoedit-batch-panel')?.style.display !== 'none';
    const tasks = batch
        ? autoEditBatchTasks.filter(autoEditBatchTaskHasIssues).map(task => ({ ...task, result: getAutoEditBatchLiveResult(task) }))
        : [{ script: document.getElementById('autoedit-script')?.value || '', clips: autoEditFiles, result: autoEditLastResult }];
    if (batch) {
        tasks.push(...window.AutoEditGeneration.unassignedScripts(autoEditBatchTasks, autoEditBatchScriptCells, autoEditBatchUnmatchedScripts)
            .filter(item => String(item.script || '').trim()).map(item => ({ script: item.script, clips: [], result: null })));
    }
    const matches = tasks.flatMap(task => window.AutoEditGeneration.collectIssues(task).map(issue => window.AutoEditGeneration.matchIssue(issue, task, records)));
    const selected = matches.flatMap(match => match.selected);
    if (!selected.length) {
        showToast('没有可靠匹配的生成资料，请点击「匹配 / 复制问题生成资料」核对候选', 'warning');
        return false;
    }
    return sendAutoEditGenerationRowsToHedra(selected, { autoStart }, triggerBtn);
}
window.sendAutoEditMatchedProblemGenerationToHedra = sendAutoEditMatchedProblemGenerationToHedra;

async function sendAutoEditSegmentGenerationToHedra(reviewIndex, batchTaskIndex = null, source = '', options = {}, triggerBtn = null) {
    const isButtonLike = val => Boolean(val && typeof val === 'object' && ('tagName' in val || 'nodeType' in val || 'disabled' in val || typeof val.closest === 'function'));
    if (isButtonLike(reviewIndex)) {
        const btn = reviewIndex;
        const idx = batchTaskIndex;
        const opts = (source && typeof source === 'object') ? source : {};
        reviewIndex = idx;
        batchTaskIndex = null;
        source = '';
        options = opts;
        triggerBtn = btn;
    }
    const autoStart = Boolean(options?.autoStart);
    const api = window.AutoEditGeneration;
    if (!api) { showToast('生成资料模块未加载', 'warning'); return false; }
    const task = batchTaskIndex !== null ? autoEditBatchTasks[batchTaskIndex] : autoEditReviewOwnerTask;
    if (batchTaskIndex !== null && !task) { showToast('当前任务已变化，请重新打开审核', 'warning'); return false; }
    const result = task && batchTaskIndex !== null ? getAutoEditBatchLiveResult(task) : autoEditLastResult;
    const rowEl = !source && triggerBtn && typeof triggerBtn.closest === 'function' ? triggerBtn.closest('.autoedit-review-row') : null;
    let rowSource = '';
    if (rowEl?.dataset?.source) {
        try { rowSource = decodeURIComponent(rowEl.dataset.source); } catch (_) { rowSource = ''; }
    }
    const effectiveSource = typeof source === 'string' && source ? source : rowSource;
    const segment = (effectiveSource ? result?.segments?.find(item => item.source === effectiveSource) : null)
        || (!source ? result?.segments?.[reviewIndex] : null);
    if (!segment) { showToast('当前片段已变化，请重新打开审核', 'warning'); return false; }
    const liveScript = rowEl?.querySelector?.('.ae-review-script')?.value ?? segment.script ?? '';
    const raw = getEffectiveAutoEditGenerationTableRaw(result, task);
    const owner = task || { result, script: result?.script_text || '', clips: result?.clips || (result?.segments || []).map(item => item.source) };
    if (raw.trim()) {
        let records = [];
        try { records = api.parseTable(raw); } catch (_) {}
        if (records.length) {
            const issue = {
                kind: 'segment',
                source: segment.source,
                text: liveScript,
                recognized: segment.recognized_text || '',
                startLine: segment.script_start_line,
                endLine: segment.script_end_line,
            };
            const byName = api.matchReviewGroup({ groupName: issue.source, suite: owner.outputName || owner.name || '' }, records);
            const match = byName.selected.length ? byName : api.matchIssue(issue, owner, records);
            if (match.selected.length) {
                return sendAutoEditGenerationRowsToHedra(match.selected, { autoStart }, triggerBtn);
            }
        }
    }
    // 兜底：若未粘贴生成资料表格，直接通过当前片段原文件名和文案回传 Hedra 匹配重跑
    const rawFile = String(segment.source || '').split(/[/\\]/).pop().replace(/\.(mp4|mov|mkv|webm|avi|m4v)$/i, '').replace(/(?:\s+[(（]\s*\d+\s*[)）]|[_-]v\d+|[_-]副本\d*)+$/gi, '').trim();
    const suitePrefix = rawFile.match(/^(.*?)[-_]片段\s*\d+/i)?.[1] || String(owner?.outputName || owner?.name || '').trim();
    if (rawFile || liveScript) {
        return sendAutoEditGenerationRowsToHedra([{
            imageName: suitePrefix,
            groupName: rawFile,
            prompt: String(liveScript || '').trim(),
            spokenScript: String(liveScript || '').trim(),
            suiteName: suitePrefix,
            keepExistingPrompt: true,
        }], { autoStart }, triggerBtn);
    }
    showToast('未找到对应的生成资料', 'warning');
    return false;
}
window.sendAutoEditSegmentGenerationToHedra = sendAutoEditSegmentGenerationToHedra;

async function sendAutoEditMissingGenerationToHedra(button, { autoStart = false } = {}) {
    const card = button?.closest('.autoedit-missing-placeholder');
    if (!card || !autoEditLastResult) return false;
    const api = window.AutoEditGeneration;
    const missingText = decodeURIComponent(card.dataset.missingText || '').trim();
    const startLine = Number(card.dataset.scriptStartLine);
    const endLine = Number(card.dataset.scriptEndLine);
    const suitePrefix = decodeURIComponent(card.dataset.suitePrefix || '').trim();
    let inferredMissingNames = [];
    try {
        if (card.dataset.inferredMissingNames) {
            inferredMissingNames = JSON.parse(decodeURIComponent(card.dataset.inferredMissingNames));
        }
    } catch (_) {}

    const result = autoEditLastResult;
    const task = autoEditReviewOwnerTask;
    const owner = task || { result, script: result?.script_text || '', clips: result?.clips || (result?.segments || []).map(item => item.source) };
    const raw = getEffectiveAutoEditGenerationTableRaw(result, task);
    if (api && raw.trim()) {
        let records = [];
        try { records = api.parseTable(raw); } catch (_) {}
        if (records.length) {
            const match = api.matchIssue({
                kind: 'missing',
                source: '',
                text: missingText,
                startLine,
                endLine,
                inferredMissingNames,
            }, owner, records);
            if (match.selected.length) {
                return sendAutoEditGenerationRowsToHedra(match.selected, { autoStart }, button);
            }
        }
    }

    // 兜底：即使未导入生成资料表格，也可凭智能推断出的缺失片段名（如 xxx-片段1）+ 缺失文案直接回传 Hedra 精准匹配重跑
    if (inferredMissingNames.length > 0) {
        const fallbackRows = inferredMissingNames.map(name => ({
            imageName: suitePrefix,
            groupName: name,
            prompt: missingText,
            spokenScript: missingText,
            suiteName: suitePrefix,
            keepExistingPrompt: true,
        }));
        return sendAutoEditGenerationRowsToHedra(fallbackRows, { autoStart }, button);
    }
    if (missingText) {
        return sendAutoEditGenerationRowsToHedra([{
            imageName: suitePrefix,
            groupName: suitePrefix,
            prompt: missingText,
            spokenScript: missingText,
            suiteName: suitePrefix,
            keepExistingPrompt: true,
        }], { autoStart }, button);
    }
    showToast('未找到对应的缺失片段生成资料', 'warning');
    return false;
}
window.sendAutoEditMissingGenerationToHedra = sendAutoEditMissingGenerationToHedra;

async function sendAutoEditCurrentTaskProblemsToHedra(optionsOrBtn = {}, maybeOptsOrBtn = null) {
    const isBtn = Boolean(optionsOrBtn && typeof optionsOrBtn === 'object' && ('tagName' in optionsOrBtn || 'nodeType' in optionsOrBtn || 'disabled' in optionsOrBtn || typeof optionsOrBtn.closest === 'function'));
    const triggerBtn = isBtn ? optionsOrBtn : maybeOptsOrBtn;
    const opts = isBtn ? (maybeOptsOrBtn || {}) : (optionsOrBtn || {});
    const autoStart = Boolean(opts.autoStart);
    if (document.querySelector('.autoedit-review-row')) persistAutoEditBatchReview();
    const result = autoEditLastResult;
    if (!result) {
        return sendAutoEditMatchedProblemGenerationToHedra({ autoStart }, triggerBtn);
    }
    const task = autoEditReviewOwnerTask || {
        script: document.getElementById('autoedit-script')?.value || result.script_text || '',
        clips: result.clips || (result.segments || []).map(item => item.source),
        result,
    };
    const api = window.AutoEditGeneration;
    const raw = getEffectiveAutoEditGenerationTableRaw(result, autoEditReviewOwnerTask);
    let records = [];
    if (api && raw.trim()) {
        try { records = api.parseTable(raw); } catch (_) {}
    }

    const outRows = [];
    // 1. 收集当前审核页所有未归属的缺失占位（V2 待确认占位）
    const missingCards = Array.from(document.querySelectorAll('.autoedit-missing-placeholder')).filter(c => c.dataset.assigned !== 'true');
    for (const card of missingCards) {
        const missingText = decodeURIComponent(card.dataset.missingText || '').trim();
        const startLine = Number(card.dataset.scriptStartLine);
        const endLine = Number(card.dataset.scriptEndLine);
        const suitePrefix = decodeURIComponent(card.dataset.suitePrefix || '').trim();
        let inferredMissingNames = [];
        try {
            if (card.dataset.inferredMissingNames) {
                inferredMissingNames = JSON.parse(decodeURIComponent(card.dataset.inferredMissingNames));
            }
        } catch (_) {}
        let matched = false;
        if (api && records.length) {
            const m = api.matchIssue({ kind: 'missing', source: '', text: missingText, startLine, endLine, inferredMissingNames }, task, records);
            if (m.selected.length) {
                outRows.push(...m.selected);
                matched = true;
            }
        }
        if (!matched && (inferredMissingNames.length || missingText)) {
            if (inferredMissingNames.length) {
                inferredMissingNames.forEach(name => outRows.push({
                    imageName: suitePrefix,
                    groupName: name,
                    prompt: missingText,
                    spokenScript: missingText,
                    suiteName: suitePrefix,
                    keepExistingPrompt: true,
                }));
            } else {
                outRows.push({
                    imageName: suitePrefix,
                    groupName: suitePrefix,
                    prompt: missingText,
                    spokenScript: missingText,
                    suiteName: suitePrefix,
                    keepExistingPrompt: true,
                });
            }
        }
    }

    // 2. 收集当前审核页所有警告/异常/未匹配片段行
    const segments = Array.isArray(result.segments) ? result.segments : [];
    segments.forEach(seg => {
        if (seg.enabled === false || seg.is_hook === true || seg.review_acknowledged === true) return;
        const matchPercent = typeof getAutoEditReviewMatchPercent === 'function' ? getAutoEditReviewMatchPercent(seg, result.language) : 100;
        const isProblem = seg.status === 'warning' || seg.status === 'error' || matchPercent < 75 || !seg.script || !seg.recognized_text;
        if (!isProblem) return;
        let matched = false;
        if (api && records.length) {
            const byName = api.matchReviewGroup({ groupName: seg.source, suite: task.outputName || task.name || '' }, records);
            const m = byName.selected.length ? byName : api.matchIssue({
                kind: 'segment',
                source: seg.source,
                text: seg.script || '',
                recognized: seg.recognized_text || '',
                startLine: seg.script_start_line,
                endLine: seg.script_end_line,
            }, task, records);
            if (m.selected.length) {
                outRows.push(...m.selected);
                matched = true;
            }
        }
        if (!matched && seg.source) {
            const rawFile = String(seg.source || '').split(/[/\\]/).pop().replace(/\.(mp4|mov|mkv|webm|avi|m4v)$/i, '').replace(/(?:\s+[(（]\s*\d+\s*[)）]|[_-]v\d+|[_-]副本\d*)+$/gi, '').trim();
            const suitePrefix = rawFile.match(/^(.*?)[-_]片段\s*\d+/i)?.[1] || String(task.outputName || task.name || '').trim();
            outRows.push({
                imageName: suitePrefix,
                groupName: rawFile,
                prompt: String(seg.script || '').trim(),
                spokenScript: String(seg.script || '').trim(),
                suiteName: suitePrefix,
                keepExistingPrompt: true,
            });
        }
    });

    if (!outRows.length) {
        showToast('本套当前没有待处理的缺失文案或异常片段', 'info');
        return false;
    }
    return sendAutoEditGenerationRowsToHedra(outRows, { autoStart }, triggerBtn);
}
window.sendAutoEditCurrentTaskProblemsToHedra = sendAutoEditCurrentTaskProblemsToHedra;

function getVkBridgeMode() {
    const runtimeMode = window.electronAPI?.runtimeMode;
    if (runtimeMode === 'dev' || runtimeMode === 'packaged') return runtimeMode;
    return window.location?.protocol === 'http:' || window.location?.protocol === 'https:' ? 'dev' : 'packaged';
}

function getVkBridgeInstanceId() {
    const mode = getVkBridgeMode();
    try {
        const key = 'vk_hedra_bridge_instance_id';
        let id = sessionStorage.getItem(key);
        if (!id || !id.startsWith(`vk_${mode}_`)) {
            id = `vk_${mode}_${Math.random().toString(36).slice(2, 7)}`;
            sessionStorage.setItem(key, id);
        }
        return id;
    } catch (_) {
        if (!window.__vkBridgeInstanceId) {
            window.__vkBridgeInstanceId = `vk_${mode}_${Math.random().toString(36).slice(2, 7)}`;
        }
        return window.__vkBridgeInstanceId;
    }
}

const hedraImportInFlight = new Map();
const hedraImportReceipts = new Map();
let hedraImportQueue = Promise.resolve();
let hedraLastImportPayload = null;
async function reportHedraImportReceipt(payload, status, detail = {}) {
    const receipt = {id: String(payload.id || ''), status, timestamp: Date.now(),
        instanceId: getVkBridgeInstanceId(), mode: getVkBridgeMode(), ...detail};
    if (payload.id && (status === 'imported' || status === 'failed')) hedraImportReceipts.set(payload.id, receipt);
    if (status !== 'skipped' && !detail.silent) {
        const panel = document.getElementById('hedra-import-feedback');
        if (panel) {
            panel.hidden = false;
            const label = panel.querySelector('[data-role="message"]');
            if (label) label.textContent = detail.message || status;
            panel.dataset.status = status;
            panel.style.color = status === 'failed' ? '#fca5a5' : status === 'imported' ? '#86efac' : '#fde047';
            const retry = panel.querySelector('button');
            if (retry) retry.hidden = status !== 'failed';
        }
        try { localStorage.setItem('videokit_hedra_import_feedback', JSON.stringify(receipt)); } catch (_) {}
    }
    try {
        const dir = getHedraBridgeDir();
        if (payload.id && dir && window.electronAPI?.writeFileText) {
            const safe = value => String(value).replace(/[^a-zA-Z0-9_-]/g, '_');
            await window.electronAPI.writeFileText(window.electronAPI.pathJoin(dir,
                `vk-import-${safe(payload.id)}-${safe(receipt.instanceId)}.json`), JSON.stringify(receipt, null, 2));
        }
    } catch (error) { console.warn('[Hedra] 写入接收回执失败', error); }
    return receipt;
}
window.retryLastHedraImport = () => hedraLastImportPayload
    ? handleHedraImportAutoEdit(hedraLastImportPayload, {force: true}) : pullGenerationAndFoldersFromHedra();

function getHedraImportBatchKey(payload) {
    const folders = [...new Set((payload.folders || []).filter(Boolean).map(value => String(value)
        .replace(/\\/g, '/').replace(/\/+$/, '').normalize('NFC')))].sort();
    // Request IDs change on every push. Folder identity stays stable for the same batch.
    return folders.length ? JSON.stringify(['folders', folders])
        : JSON.stringify(['generation', String(payload.generationTableText || '').replace(/\r\n?/g, '\n').trim()]);
}
function prepareHedraImportWorkspace(payload) {
    const key = getHedraImportBatchKey(payload);
    saveAutoEditWorkspaceState();
    const existingIndex = autoEditWorkspaces.findIndex(workspace => workspace.hedraBatchKey === key
        || (!workspace.hedraPendingBatchKey && workspace.state?.tasks?.some(task => task.clips?.length)
            && getHedraImportBatchKey({folders: workspace.state.tasks.map(task => task.folder)}) === key));
    if (existingIndex >= 0) {
        const workspace = autoEditWorkspaces[existingIndex];
        workspace.hedraBatchKey = key;
        const requested = new Set((payload.folders || []).map(folder => String(folder).replace(/\\/g, '/').replace(/\/+$/, '').normalize('NFC')));
        const tasks = (workspace.state?.tasks || []).filter(task => !requested.size || requested.has(String(task.folder).replace(/\\/g, '/').replace(/\/+$/, '').normalize('NFC')));
        const nextGenTable = String(payload.generationTableText || '').trim();
        if (nextGenTable) {
            try {
                window.AutoEditGeneration?.parseTable?.(nextGenTable);
                tasks.forEach(task => {
                    task.hedraGenerationTable = nextGenTable;
                    if (task.result) task.result.generation_table = nextGenTable;
                });
                if (workspace.state?.fields?.['autoedit-generation-table']) {
                    workspace.state.fields['autoedit-generation-table'].value = nextGenTable;
                }
                if (existingIndex === autoEditWorkspaceIndex) {
                    const genInput = document.getElementById('autoedit-generation-table');
                    if (genInput) {
                        genInput.value = nextGenTable;
                        renderAutoEditGenerationImport?.();
                    }
                }
            } catch (_) {}
        }
        return {duplicate: true, workspace, taskCount: tasks.length,
            clipCount: tasks.reduce((n, task) => n + (task.clips?.length || 0), 0)};
    }
    const pendingIndex = autoEditWorkspaces.findIndex(workspace => workspace.hedraPendingBatchKey === key);
    if (pendingIndex >= 0) {
        if (pendingIndex !== autoEditWorkspaceIndex) switchAutoEditWorkspace(pendingIndex);
        return {duplicate: false, workspace: autoEditWorkspaces[pendingIndex], key};
    }
    // Reuse an untouched empty tab; every populated batch gets a separate tab.
    const current = autoEditWorkspaces[autoEditWorkspaceIndex];
    const state = current?.state || {};
    const hasContent = current?.hedraBatchKey || state.tasks?.length || state.files?.length || state.result
        || ['autoedit-script','autoedit-batch-paste','autoedit-generation-table'].some(id => String(state.fields?.[id]?.value || '').trim());
    if (hasContent || state.mode === 'single') switchAutoEditWorkspace(-1, 'batch');
    const workspace = autoEditWorkspaces[autoEditWorkspaceIndex];
    const parts = String(payload.outputDir || payload.folders?.[0] || '').replace(/\\/g,'/').replace(/\/+$/,'').split('/');
    const base = `生成端 · ${parts.pop() || `批量任务 ${autoEditWorkspaceIndex + 1}`}`;
    let name = base, suffix = 2;
    while (autoEditWorkspaces.some(tab => tab !== workspace && tab.name === name)) name = `${base} (${suffix++})`;
    workspace.name = name;
    workspace.hedraPendingBatchKey = key;
    renderAutoEditWorkspaceTabs();
    return {duplicate: false, workspace, key};
}

async function handleHedraImportAutoEdit(payload, options = {}) {
    if (!payload || typeof payload !== 'object') return false;
    // 若 Hedra 端指定了目标 VK 实例或目标版本，非目标窗口直接忽略（不打扰其他多开的 VK 窗口）
    if (!options.force) {
        const myMode = getVkBridgeMode();
        const myInstanceId = getVkBridgeInstanceId();
        if (payload.targetInstanceId && payload.targetInstanceId !== 'all') {
            if (payload.targetInstanceId !== myInstanceId && payload.targetInstanceId !== myMode) {
                await reportHedraImportReceipt(payload, 'skipped', {message: '指定的 VideoKit Studio 窗口已变化，请在生成端重新选择接收窗口后推送'});
                return false;
            }
        }
        if (payload.targetMode && payload.targetMode !== 'all' && payload.targetMode !== myMode) {
            await reportHedraImportReceipt(payload, 'skipped', {message: '推送指定的是另一个 VideoKit 版本'});
            return false;
        }
    }
    if (payload.id && hedraImportInFlight.has(payload.id)) return hedraImportInFlight.get(payload.id);
    if (payload.id && !options.force && hedraImportReceipts.get(payload.id)?.status === 'failed') {
        await reportHedraImportReceipt(payload, 'failed', {...hedraImportReceipts.get(payload.id), silent: true});
        return false;
    }
    if (payload.id && !options.force && hedraHandledPushIds.has(payload.id)
        && autoEditWorkspaces.some(workspace => workspace.hedraBatchKey === getHedraImportBatchKey(payload))) {
        // HTTP 与文件桥是同一请求的两条传输路径，第二次到达只补回执，不重复提示。
        await reportHedraImportReceipt(payload, 'imported', {...(hedraImportReceipts.get(payload.id) || {}), silent: true});
        return true;
    }
    hedraLastImportPayload = payload;
    if (typeof invalidateHedraFallbackSnapshotCache === 'function') invalidateHedraFallbackSnapshotCache();
    const work = hedraImportQueue.then(async () => {


    try {
        await reportHedraImportReceipt(payload, 'processing', {message: '正在接收生成端推送并读取视频文件夹…'});
        if (autoEditBatchRunning || autoEditActiveRequestIds.size) throw new Error('当前正在分析或导出，请等待完成后点击“重试接收”');
        const batch = prepareHedraImportWorkspace(payload);
        if (batch.duplicate) {
            const message = `本批次已经在 VK 标签页「${batch.workspace.name}」，无需再次推送`;
            if (payload.id) hedraHandledPushIds.add(payload.id);
            await reportHedraImportReceipt(payload, 'imported', {message, alreadyPresent: true,
                workspaceName: batch.workspace.name, taskCount: batch.taskCount, clipCount: batch.clipCount});
            showToast(message, 'info', 7000);
            return true;
        }
        // 1. 切换到「媒体转换 -> 文案自动剪辑 -> 批量任务」
        if (typeof switchModule === 'function') switchModule('media');
        if (typeof switchSubTab === 'function') switchSubTab('media', 'media-autoedit');
        if (typeof setAutoEditMode === 'function') setAutoEditMode('batch');

        // 2. 填入生成资料表格（5列）
        const genTableText = String(payload.generationTableText || '').trim();
        const genInput = document.getElementById('autoedit-generation-table');
        if (genTableText && !genInput) throw new Error('生成资料接收区域尚未加载，请刷新 VideoKit 后重试');
        if (genTableText) window.AutoEditGeneration.parseTable(genTableText);
        if (genTableText && genInput) {
            genInput.value = genTableText;
            renderAutoEditGenerationImport();
        }

        // 3. 载入套文件夹
        const folders = Array.isArray(payload.folders) ? payload.folders.filter(Boolean) : [];
        if (!folders.length && !genTableText) throw new Error('推送中没有视频文件夹或生成资料');
        for (const folder of folders) {
            const stat = window.electronAPI?.fsStat?.(folder);
            if (!stat?.isDirectory) throw new Error(`推送的文件夹不存在或无法读取：${folder}`);
        }
        if (folders.length) {
            await loadAutoEditBatchFolders(folders, {
                replace: true,
                preservePastedScripts: true,
            });
        }

        const importedTasks = folders.length ? autoEditBatchTasks.filter(task => folders.some(folder =>
            normalizeAutoEditBatchPath(task.folder) === normalizeAutoEditBatchPath(folder))) : [];
        if (folders.length && !importedTasks.length) throw new Error('没有载入任何任务文件夹，请检查文件夹权限后重试');
        if (folders.length && !importedTasks.some(task => task.clips?.length)) throw new Error('文件夹已读取，但没有找到可用视频；请检查成片路径或筛选规则');
        if (genTableText) {
            // 锁定当前 Hedra 推送批次的生成资料与原任务坐标，防止旧历史工程覆盖或混入同名批次
            if (genInput && genInput.value !== genTableText) {
                genInput.value = genTableText;
                renderAutoEditGenerationImport();
            }
            importedTasks.forEach(task => {
                task.hedraGenerationTable = genTableText;
                if (task.result) task.result.generation_table = genTableText;
            });
        }
        // 4. 自动回填提取出的口播文案（仅对尚未填写文案的任务或按套匹配回填）
        const scriptsBySuite = payload.scriptsBySuite && typeof payload.scriptsBySuite === 'object' ? payload.scriptsBySuite : {};
        let filledScriptCount = 0;
        if (Object.keys(scriptsBySuite).length && autoEditBatchTasks.length) {
            const normSuite = s => String(s || '').trim().normalize('NFKC').toLowerCase();
            const suiteEntries = Object.entries(scriptsBySuite).map(([k, v]) => [normSuite(k), String(v || '').trim()]);
            autoEditBatchTasks.forEach(task => {
                if (payload.fillMissingScripts !== false && String(task.script || '').trim()) return;
                const taskSuiteKey = normSuite(task.outputName || task.name);
                const exact = suiteEntries.find(([k]) => k === taskSuiteKey);
                const fuzzy = exact || suiteEntries.find(([k]) => k && taskSuiteKey && (k.includes(taskSuiteKey) || taskSuiteKey.includes(k)));
                if (fuzzy && fuzzy[1]) {
                    setAutoEditBatchTaskScript(task, fuzzy[1]);
                    filledScriptCount++;
                }
            });
            if (filledScriptCount > 0) {
                syncAutoEditBatchParallelLists();
                renderAutoEditBatchTasks();
            }
        }

        // 与“自动断行全部文案”按钮共用同一流程，先断行再触发分析。
        // 重复批次在前面直接返回，不会再次改动已有标签页的文案。
        const autoWrapped = importedTasks.some(task => String(task.script || '').trim());
        if (autoWrapped) autoBreakAutoEditBatchScripts(undefined, {silent: true});
        saveAutoEditWorkspaceState?.();
        renderAutoEditBatchTasks();

        showToast(
            `✂️ 已从生成端载入 ${folders.length} 套任务文件夹${genTableText ? `、${payload.rowCount || ''} 条生成资料` : ''}${filledScriptCount ? `，并自动填入 ${filledScriptCount} 套口播文案` : ''}`,
            'success',
            6500
        );

        // 5. 若勾选了推送并立即分析，则自动启动批量分析
        if (payload.autoAnalyze && autoEditBatchTasks.some(t => t.clips?.length && String(t.script || '').trim())) {
            setTimeout(() => {
                if (!autoEditBatchRunning) {
                    startAutoEditBatchAnalysis();
                }
            }, 250);
        }
        batch.workspace.hedraBatchKey = batch.key;
        delete batch.workspace.hedraPendingBatchKey;
        saveAutoEditWorkspaceState();
        if (payload.id) hedraHandledPushIds.add(payload.id);
        await reportHedraImportReceipt(payload, 'imported', {workspaceName: batch.workspace.name, taskCount: importedTasks.length,
            clipCount: importedTasks.reduce((n, task) => n + (task.clips?.length || 0), 0),
            message: folders.length ? `已接收生成端推送：${importedTasks.length} 个任务已载入标签页「${batch.workspace.name}」${autoWrapped ? '，文案已自动断行' : ''}`
                : '已收到生成资料，但推送中没有视频文件夹，因此没有新增视频任务'});
        return true;
    } catch (err) {
        await reportHedraImportReceipt(payload, 'failed', {message: `接收生成端推送失败：${err?.message || err}`});
        showToast(`载入生成端批次失败：${err?.message || err}`, 'error');
        return false;
    }
    });
    hedraImportQueue = work.catch(() => false);
    if (payload.id) hedraImportInFlight.set(payload.id, work);
    try { return await work; } finally { if (payload.id) hedraImportInFlight.delete(payload.id); }
}
window.handleHedraImportAutoEdit = handleHedraImportAutoEdit;

function extractSpokenScriptFromHedraPrompt(prompt) {
    const raw = String(prompt || '').trim();
    if (!raw) return '';
    const m1 = raw.match(/(?:台词内容|台词|文案|对白|旁白|口播)\s*[:：]\s*[“"「『]([\s\S]*?)[”"」』]\s*(?=\r?\n|$|【)/i);
    if (m1?.[1]?.trim()) return m1[1].trim();
    const m2 = raw.match(/(?:台词内容|台词|文案|对白|旁白|口播)\s*[:：]\s*([^\r\n【]+)/i);
    if (m2?.[1]?.trim()) return m2[1].trim().replace(/^[“"「『]+|[”"」』]+$/g, '').trim();
    const m3 = raw.match(/\b(?:says|speaking|speaks|spoken|script|dialogue|voiceover)\s*[:：]\s*[“"「『]([\s\S]*?)[”"」』]/i);
    if (m3?.[1]?.trim()) return m3[1].trim();
    const quotes = [...raw.matchAll(/[“"]([^”"\r\n]{12,})[”"]/g)].map(m => m[1].trim());
    if (quotes.length === 1) return quotes[0];
    return '';
}

const _cachedLocalHedraStateFiles = new Map();
let _cachedLocalHedraResultMeta = { key: '', result: null };
let _hedraBridgeEnsuredDir = '';
let _lastVkHeartbeatAt = 0;

function readLocalHedraFlowPoolState() {
    try {
        const autoSavePath = window.electronAPI?.legacyAutoSavePath;
        if (!autoSavePath || !window.electronAPI?.pathDirname || !window.electronAPI?.pathJoin || !window.electronAPI?.readFileText || !window.electronAPI?.fsStat) {
            return null;
        }
        const homeDir = window.electronAPI.pathDirname(window.electronAPI.pathDirname(autoSavePath));
        const appSupport = window.electronAPI.pathJoin(homeDir, 'Library', 'Application Support');
        const candidates = [
            window.electronAPI.pathJoin(appSupport, 'electron-playwright-auto-login-to-hedrax12', 'flow-pool', 'state.json'),
            window.electronAPI.pathJoin(appSupport, 'electron-playwright-auto-login-to-hedrax111', 'flow-pool', 'state.json'),
        ];
        const parsedCandidates = [];
        for (const p of candidates) {
            const st = window.electronAPI.fsStat(p);
            if (!st) {
                _cachedLocalHedraStateFiles.delete(p);
                continue;
            }
            const cached = _cachedLocalHedraStateFiles.get(p);
            if (cached && cached.mtimeMs === st.mtimeMs && cached.size === st.size) {
                if (cached.state && Array.isArray(cached.state.rows)) {
                    parsedCandidates.push({ path: p, mtimeMs: st.mtimeMs, size: st.size, state: cached.state });
                }
                continue;
            }
            const raw = window.electronAPI.readFileText(p);
            if (!raw) continue;
            try {
                const state = JSON.parse(raw);
                _cachedLocalHedraStateFiles.set(p, { mtimeMs: st.mtimeMs, size: st.size, state });
                if (state && Array.isArray(state.rows)) {
                    parsedCandidates.push({ path: p, mtimeMs: st.mtimeMs, size: st.size, state });
                }
            } catch (_) {}
        }
        if (!parsedCandidates.length) {
            _cachedLocalHedraResultMeta = { key: '', result: null };
            return null;
        }
        // 优先选择有任务行的实例；若都有任务行，则选择最近更新的实例
        parsedCandidates.sort((a, b) => {
            const aHas = a.state.rows.length > 0 ? 1 : 0;
            const bHas = b.state.rows.length > 0 ? 1 : 0;
            if (aHas !== bHas) return bHas - aHas;
            return b.mtimeMs - a.mtimeMs;
        });
        const cacheKey = parsedCandidates.map(c => `${c.path}:${c.mtimeMs}:${c.size}:${c.state.rows.length}`).join('|');
        if (_cachedLocalHedraResultMeta.key === cacheKey && _cachedLocalHedraResultMeta.result) {
            return _cachedLocalHedraResultMeta.result;
        }
        const chosen = parsedCandidates[0];
        const bestPath = chosen.path;
        const state = chosen.state;

        const settings = state.settings || {};
        const baseOut = String(settings.outputDir || '').trim();
        const sub = String(settings.currentBatchSubdir || '').trim();
        let effectiveOut = baseOut;
        if (baseOut && sub && settings.outputBatchMode === 'date_batch') {
            const subPath = window.electronAPI.pathJoin(baseOut, sub);
            if (window.electronAPI.fsStat(subPath)?.isDirectory) effectiveOut = subPath;
        }

        const suiteNameOf = groupName => {
            const clean = String(groupName || '').trim().replace(/\.(mp4|mov|mkv|webm)$/i, '');
            return clean.replace(/[-_]片段\s*\d+(?:\s*[(（]\d+[)）])?.*$/i, '').trim() || clean;
        };

        const suiteOrder = [];
        const suiteSeen = new Set();
        const firstOutputBySuite = new Map();
        for (const r of state.rows) {
            const s = suiteNameOf(r.groupName);
            if (s && !suiteSeen.has(s)) {
                suiteSeen.add(s);
                suiteOrder.push(s);
            }
            if (s && r.outputPath && !firstOutputBySuite.has(s)) {
                firstOutputBySuite.set(s, r.outputPath);
            }
        }

        const folders = [];
        const folderSeen = new Set();
        for (const s of suiteOrder) {
            if (effectiveOut) {
                const suiteDir = window.electronAPI.pathJoin(effectiveOut, s);
                if (window.electronAPI.fsStat(suiteDir)?.isDirectory && !folderSeen.has(suiteDir)) {
                    folderSeen.add(suiteDir);
                    folders.push(suiteDir);
                    continue;
                }
            }
            const outPath = firstOutputBySuite.get(s);
            if (outPath) {
                const parentDir = window.electronAPI.pathDirname(outPath);
                if (parentDir && window.electronAPI.fsStat(parentDir)?.isDirectory && !folderSeen.has(parentDir)) {
                    folderSeen.add(parentDir);
                    folders.push(parentDir);
                }
            }
        }

        const tabByRowId = new Map();
        for (const tab of state.taskTabs || []) {
            for (const row of tab?.rows || []) {
                if (row?.id && !tabByRowId.has(row.id)) tabByRowId.set(row.id, tab);
            }
        }
        const sourceIdPrefix = 'flow-store:' + window.electronAPI.pathDirname(bestPath).replace(/\\/g, '/').normalize('NFC');
        const escapeCell = v => `"${String(v ?? '').replace(/"/g, '""')}"`;
        const tsvLines = [];
        const suiteSegs = new Map();
        state.rows.forEach((r, idx) => {
            const sName = suiteNameOf(r.groupName);
            const imgCell = r.imageName || (r.imagePath ? window.electronAPI.pathBasename(r.imagePath) : sName);
            const rawGroup = String(r.groupName || '').trim();
            const namingCell = rawGroup ? (/\.(mp4|mov|mkv|webm)$/i.test(rawGroup) ? rawGroup : `${rawGroup}.mp4`) : '';
            const promptCell = String(r.prompt || '').trim();
            const spoken = extractSpokenScriptFromHedraPrompt(promptCell);
            if (promptCell) {
                const tab = r.id ? tabByRowId.get(r.id) : null;
                const origin = tab && r.id ? {sourceId: sourceIdPrefix, tabId: tab.id, rowId: r.id, tabName: tab.name} : null;
                const cols = [imgCell, '', namingCell, promptCell, spoken || '', origin ? JSON.stringify({hedraOrigin: origin}) : ''];
                tsvLines.push(cols.map(escapeCell).join('\t'));
            }
            if (spoken && sName) {
                const m = rawGroup.match(/片段\s*(\d+)(?:[(（](\d+)[)）])?/i);
                const segNum = m ? Number(m[1]) + (m[2] ? Number(m[2]) / 1000 : 0) : idx + 1;
                if (!suiteSegs.has(sName)) suiteSegs.set(sName, []);
                suiteSegs.get(sName).push({ segNum, idx, spoken });
            }
        });

        const scriptsBySuite = {};
        for (const [sName, arr] of suiteSegs.entries()) {
            arr.sort((a, b) => a.segNum - b.segNum || a.idx - b.idx);
            const text = arr.map(x => x.spoken.trim()).filter(Boolean).join('\n');
            if (text) scriptsBySuite[sName] = text;
        }

        const builtResult = {
            sourcePath: bestPath,
            mode: bestPath.includes('hedrax12') ? 'packaged' : 'dev',
            rawRows: state.rows,
            allInstances: parsedCandidates.map(c => ({
                mode: c.path.includes('hedrax12') ? 'packaged' : 'dev',
                rowCount: c.state.rows.length,
            })),
            rowCount: state.rows.length,
            suiteCount: folders.length || suiteOrder.length,
            payload: {
                id: `local_state_${chosen.mtimeMs}`,
                timestamp: chosen.mtimeMs || Date.now(),
                folders,
                suiteNames: suiteOrder,
                generationTableText: tsvLines.join('\n'),
                scriptsBySuite,
                replace: true,
                fillMissingScripts: true,
                outputDir: effectiveOut,
                rowCount: tsvLines.length,
                suiteCount: folders.length,
            },
        };
        _cachedLocalHedraResultMeta = { key: cacheKey, result: builtResult };
        return builtResult;
    } catch (_) {
        return null;
    }
}

async function refreshHedraBridgeStatus(manual = false) {
    const badges = document.querySelectorAll('[data-role="hedra-bridge-status-badge"]');
    const applyBadge = (text, border, bg, color, title) => {
        badges.forEach(el => {
            el.textContent = text;
            el.style.borderColor = border;
            el.style.background = bg;
            el.style.color = color;
            if (title) el.title = title;
        });
    };

    // 写入 VideoKit 自身心跳文件（按实例 ID 与 dev / packaged 分文件写入，支持多开 VK 时在 Hedra 手动点选目标窗口）
    try {
        const nowMs = Date.now();
        const dir = getHedraBridgeDir();
        const writeHeartbeat = window.electronAPI?.writeFileTextDeferred || window.electronAPI?.writeFileText;
        if (dir && window.electronAPI?.ensureDirectory && writeHeartbeat && window.electronAPI?.pathJoin && (manual || nowMs - _lastVkHeartbeatAt >= 6000)) {
            if (_hedraBridgeEnsuredDir !== dir) {
                window.electronAPI.ensureDirectory(dir);
                _hedraBridgeEnsuredDir = dir;
            }
            _lastVkHeartbeatAt = nowMs;
            const vkMode = getVkBridgeMode();
            const vkInstanceId = getVkBridgeInstanceId();
            const tasks = typeof autoEditBatchTasks !== 'undefined' && Array.isArray(autoEditBatchTasks) ? autoEditBatchTasks : [];
            const taskNames = tasks
                .slice(0, 3)
                .map(t => String(t?.outputName || t?.name || '').trim())
                .filter(Boolean);
            const hbPayload = JSON.stringify({
                instanceId: vkInstanceId,
                updatedAt: nowMs,
                mode: vkMode,
                taskCount: tasks.length,
                taskNames,
            });
            writeHeartbeat(window.electronAPI.pathJoin(dir, 'vk-heartbeat.json'), hbPayload);
            writeHeartbeat(window.electronAPI.pathJoin(dir, `vk-heartbeat-${vkMode}.json`), hbPayload);
            writeHeartbeat(window.electronAPI.pathJoin(dir, `vk-heartbeat-${vkInstanceId}.json`), hbPayload);
        }
    } catch (_) {}

    const allHttp = await fetchAllHedraBridges('/status', { timeoutMs: 1100 });
    const onlineHttp = allHttp.filter(r => r && r.ok);
    if (onlineHttp.length > 0) {
        if (onlineHttp.length > 1) {
            const summary = onlineHttp.map(r => `${Number(r.rowCount) || 0}条`).join(' + ');
            const totalCount = onlineHttp.reduce((s, r) => s + (Number(r.rowCount) || 0), 0);
            applyBadge(
                `🟢 生成端已连接 ${onlineHttp.length} 个队列（${summary}）`,
                'rgba(34,197,94,.65)',
                'rgba(22,163,74,.18)',
                '#86efac',
                `已同时连接 ${onlineHttp.length} 个生成端任务队列（${summary}），拉取与发回重跑会自动匹配对应批次 · 点击刷新`
            );
            if (manual) showToast(`🟢 生成端已连接 ${onlineHttp.length} 个队列（${summary}）`, 'success', 3500);
            return { connected: true, mode: 'http-multi', rowCount: totalCount, instances: onlineHttp };
        }
        const httpStatus = onlineHttp[0];
        const count = Number(httpStatus.rowCount) || 0;
        applyBadge(
            `🟢 生成端已连接（${count} 条任务）`,
            'rgba(34,197,94,.65)',
            'rgba(22,163,74,.18)',
            '#86efac',
            `生成端实时队列在线（共 ${count} 条任务）· 点击刷新`
        );
        if (manual) showToast(`🟢 生成端连接正常（当前 ${count} 条任务）`, 'success', 3000);
        return { connected: true, mode: 'http', rowCount: count };
    }

    const localState = readLocalHedraFlowPoolState();
    if (localState && localState.rowCount > 0) {
        applyBadge(
            `🟢 生成端已就绪（${localState.rowCount} 条任务 / ${localState.suiteCount} 套）`,
            'rgba(16,185,129,.6)',
            'rgba(16,185,129,.15)',
            '#6ee7b7',
            `已同步生成端本地批次数据（${localState.rowCount} 条任务、${localState.suiteCount} 套文件夹），可直接点击「📥 从生成端拉取当前批次」或发回重跑`
        );
        if (manual) showToast(`🟢 已检测到生成端当前批次（${localState.rowCount} 条任务 / ${localState.suiteCount} 套文件夹），可直接拉取或发回重跑`, 'success', 4000);
        return { connected: true, mode: 'file-bridge', rowCount: localState.rowCount };
    }

    applyBadge(
        '⚪ 生成端未检测到批次（点击刷新）',
        'rgba(148,163,184,.35)',
        'rgba(15,23,42,.55)',
        '#cbd5e1',
        '尚未检测到生成端活动批次，载入生成任务后点击此处即可刷新'
    );
    if (manual) showToast('尚未检测到生成端活动批次，请确认生成端中已有任务', 'info', 3500);
    return { connected: false };
}
window.refreshHedraBridgeStatus = refreshHedraBridgeStatus;

async function pullGenerationAndFoldersFromHedra(triggerBtn = null) {
    if (triggerBtn) triggerBtn.disabled = true;
    try {
        // 1. 优先从正在运行的 Hedra HTTP 服务实时拉取（若同时开了多个版本，优先拉取有任务行的实例）
        const allRes = await fetchAllHedraBridges('/export-current-batch?scope=all', { method: 'GET', timeoutMs: 2200 });
        const bestRes = allRes
            .filter(r => r && r.ok && r.payload && (r.payload.folders?.length || r.payload.generationTableText))
            .sort((a, b) => (Number(b.payload?.rowCount) || 0) - (Number(a.payload?.rowCount) || 0))[0];
        if (bestRes && bestRes.payload) {
            const imported = await handleHedraImportAutoEdit(bestRes.payload, { force: true });
            refreshHedraBridgeStatus(false);
            return imported;
        }
        // 2. 回退读取共享文件桥中的最新批次快照
        const dir = getHedraBridgeDir();
        if (dir && window.electronAPI?.readFileText && window.electronAPI?.pathJoin) {
            const latestRaw = window.electronAPI.readFileText(window.electronAPI.pathJoin(dir, 'hedra-latest-batch.json'))
                || window.electronAPI.readFileText(window.electronAPI.pathJoin(dir, 'pending-to-vk.json'));
            if (latestRaw) {
                const parsed = JSON.parse(latestRaw);
                const payload = parsed?.payload || parsed;
                if (payload && (payload.folders?.length || payload.generationTableText)) {
                    const imported = await handleHedraImportAutoEdit(payload, { force: true });
                    refreshHedraBridgeStatus(false);
                    return imported;
                }
            }
        }
        // 3. 直接读取本地 Hedra Flow 批量实时状态库（无需重启旧版 Hedra 也能一键拉取！）
        const localState = readLocalHedraFlowPoolState();
        if (localState?.payload && (localState.payload.folders?.length || localState.payload.generationTableText)) {
            const imported = await handleHedraImportAutoEdit(localState.payload, { force: true });
            refreshHedraBridgeStatus(false);
            return imported;
        }
        showToast('未检测到生成端当前批次，请先在生成端中载入任务或推送批次', 'warning', 5500);
        return false;
    } catch (err) {
        showToast(`从生成端拉取失败：${err?.message || err}`, 'error');
        return false;
    } finally {
        if (triggerBtn) triggerBtn.disabled = false;
    }
}
window.pullGenerationAndFoldersFromHedra = pullGenerationAndFoldersFromHedra;

async function handleHedraClipUpdated(event) {
    if (!event || typeof event !== 'object') return;
    if (event.id && hedraHandledClipEventIds.has(event.id)) return;
    if (event.id) hedraHandledClipEventIds.add(event.id);
    if (!autoEditBatchTasks.length) return;

    const normPath = p => String(p || '').replace(/\\/g, '/').replace(/\/+$/, '').normalize('NFC');
    const eventSuiteFolder = normPath(event.suiteFolder);
    const eventOutputPath = normPath(event.outputPath);
    const eventSuiteName = String(event.suiteName || '').trim().normalize('NFKC').toLowerCase();

    const matchedTask = autoEditBatchTasks.find(task => {
        const tf = normPath(task.folder);
        if (!tf) return false;
        if (eventSuiteFolder && (tf === eventSuiteFolder || tf.startsWith(eventSuiteFolder + '/') || eventSuiteFolder.startsWith(tf + '/'))) return true;
        if (eventOutputPath && eventOutputPath.startsWith(tf + '/')) return true;
        const tn = String(task.outputName || task.name || '').trim().normalize('NFKC').toLowerCase();
        return Boolean(eventSuiteName && tn && tn === eventSuiteName);
    });

    if (!matchedTask) return;

    const runTargetedRefresh = async (task, clipPaths) => {
        if (!window.electronAPI?.scanDirectory || !task.folder) return;
        const videoExt = /\.(mp4|mov|mkv|avi|wmv|flv|webm|m4v)$/i;
        const entries = await scanAutoEditBatchFolderRecursive(task.folder);
        const clips = filterAutoEditSourceVideos(entries, videoExt).map(entry => entry.path);
        task.clips = clips;
        if (!clips.length) {
            renderAutoEditBatchTasks();
            return;
        }
        const validClipPaths = clipPaths.filter(p => clips.some(c => normPath(c) === normPath(p)));
        const settings = { ...(task.settings || getAutoEditRequestSettings()) };
        if (String(task.script || '').trim() && settings.workflow_mode !== 'concat_first') {
            const reviewDialogOpen = Boolean(typeof document !== 'undefined' && document.getElementById('autoedit-batch-review-dialog')?.isConnected);
            const wasActiveReviewOwner = reviewDialogOpen && autoEditReviewOwnerTask === task;
            setAutoEditBatchRunning(true);
            try {
                await analyzeAutoEditBatchTask(task, settings, {
                    recalculateUnpassedCuts: true,
                    retranscribeClipPaths: validClipPaths.length ? validClipPaths : undefined,
                });
                saveAutoEditWorkspaceState?.();
                renderAutoEditBatchTasks();
                showToast(`🔄 生成端新成片「${(event.outputPath || '').split(/[/\\]/).pop()}」已自动重识别并更新切点`, 'success', 5500);
            } finally {
                setAutoEditBatchRunning(false);
                if (typeof document !== 'undefined' && document.getElementById('autoedit-batch-review-dialog')?.isConnected) {
                    if (wasActiveReviewOwner) {
                        const taskIdx = autoEditBatchTasks.indexOf(task);
                        if (taskIdx >= 0 && task.result) bindAutoEditBatchReviewTask(taskIdx);
                    }
                    window.AutoEditBatchIssueReview?.scheduleRefresh?.();
                }
            }
        } else {
            renderAutoEditBatchTasks();
            showToast(`🔄 已检测到生成端新成片「${(event.outputPath || '').split(/[/\\]/).pop()}」并刷新任务素材列表`, 'info', 4500);
        }
    };

    if (autoEditBatchRunning || autoEditActiveRequestIds.size) {
        const list = hedraPendingClipRefreshQueue.get(matchedTask) || [];
        if (event.outputPath && !list.includes(event.outputPath)) list.push(event.outputPath);
        hedraPendingClipRefreshQueue.set(matchedTask, list);
        showToast(`📥 收到生成端新生成的片段「${(event.outputPath || '').split(/[/\\]/).pop()}」，将在当前分析完成后自动增量更新`, 'info', 4500);
        return;
    }

    await runTargetedRefresh(matchedTask, event.outputPath ? [event.outputPath] : []);
}
window.handleHedraClipUpdated = handleHedraClipUpdated;

(function initHedraAutoEditBridgeListeners() {
    if (typeof window === 'undefined') return;
    if (window._hedraAutoEditBridgeInitialized) return;
    window._hedraAutoEditBridgeInitialized = true;
    try {
        const last = JSON.parse(localStorage.getItem('videokit_hedra_import_feedback') || 'null');
        const panel = document.getElementById('hedra-import-feedback');
        if (last?.message && panel) {
            panel.hidden = false;
            panel.querySelector('[data-role="message"]').textContent = last.message;
            panel.querySelector('button').hidden = last.status !== 'failed';
        }
    } catch (_) {}

    // 1. 监听主进程 HTTP 桥转发过来的 IPC 消息
    if (window.bridge?.on) {
        window.bridge.on('hedra:import-autoedit', payload => {
            handleHedraImportAutoEdit(payload);
        });
        window.bridge.on('hedra:clip-updated', event => {
            handleHedraClipUpdated(event);
        });
    }

    // 2. 轮询共享文件桥（不删除文件，使用 hedraHandledPushIds 去重，支持多个 VK 版本同时打开时都能收到推送）
    let lastPendingMtime = 0;
    let lastClipEventsMtime = 0;
    let bridgeTickCount = 0;
    setTimeout(() => refreshHedraBridgeStatus(false), 300);
    setInterval(() => {
        try {
            if (++bridgeTickCount % 2 === 0) {
                refreshHedraBridgeStatus(false);
            }
            // 处理挂起的增量重识别队列
            if (!autoEditBatchRunning && !autoEditActiveRequestIds.size && hedraPendingClipRefreshQueue.size > 0) {
                const nextEntry = hedraPendingClipRefreshQueue.entries().next().value;
                if (nextEntry) {
                    const [task, clipPaths] = nextEntry;
                    hedraPendingClipRefreshQueue.delete(task);
                    handleHedraClipUpdated({
                        id: `queued_${Date.now()}`,
                        suiteFolder: task.folder,
                        suiteName: task.outputName || task.name,
                        outputPath: clipPaths[0] || '',
                    });
                }
            }

            const dir = getHedraBridgeDir();
            if (!dir || !window.electronAPI?.fsStat || !window.electronAPI?.readFileText || !window.electronAPI?.pathJoin) return;

            const pendingFile = window.electronAPI.pathJoin(dir, 'pending-to-vk.json');
            const st = window.electronAPI.fsStat(pendingFile);
            if (st && st.mtimeMs > lastPendingMtime) {
                lastPendingMtime = st.mtimeMs;
                const raw = window.electronAPI.readFileText(pendingFile);
                if (raw) {
                    const data = JSON.parse(raw);
                    const payload = data?.payload || data;
                    if (payload && payload.timestamp && Date.now() - Number(payload.timestamp) < 120000) {
                        handleHedraImportAutoEdit(payload);
                    }
                }
            }

            const clipFile = window.electronAPI.pathJoin(dir, 'clip-events-to-vk.json');
            const cst = window.electronAPI.fsStat(clipFile);
            if (cst && cst.mtimeMs > lastClipEventsMtime) {
                lastClipEventsMtime = cst.mtimeMs;
                const raw = window.electronAPI.readFileText(clipFile);
                if (raw) {
                    const data = JSON.parse(raw);
                    const events = Array.isArray(data?.events) ? data.events : (data?.id ? [data] : []);
                    const recent = events.filter(ev => ev && ev.timestamp && Date.now() - Number(ev.timestamp) < 120000);
                    recent.forEach(ev => handleHedraClipUpdated(ev));
                }
            }
        } catch (_) {}
    }, 1500);
})();
function showAutoEditGenerationMatches() {
    if (document.querySelector('.autoedit-review-row')) persistAutoEditBatchReview();
    let records;
    try { records = window.AutoEditGeneration.parseTable(getEffectiveAutoEditGenerationTableRaw(autoEditLastResult, autoEditReviewOwnerTask)); }
    catch (error) { return showToast(error.message, 'error'); }
    if (!records.length) return showToast('请先粘贴生成资料表格', 'warning');
    saveAutoEditWorkspaceState();
    const batch = document.getElementById('autoedit-batch-panel')?.style.display !== 'none';
    const unassigned = batch ? window.AutoEditGeneration.unassignedScripts(
        autoEditBatchTasks, autoEditBatchScriptCells, autoEditBatchUnmatchedScripts) : [];
    const tasks = batch ? [
        ...autoEditBatchTasks.filter(autoEditBatchTaskHasIssues),
        ...unassigned.filter(item => String(item.script || '').trim()).map(item => ({
            name: `未对应视频任务的文案 #${Number(item.originalIndex) + 1}`, script: item.script, clips: [], result: null
        }))
    ] : [{
        name: autoEditCurrentFolder?.split(/[/\\]/).pop() || '单套任务', script: document.getElementById('autoedit-script')?.value || '', clips: autoEditFiles, result: autoEditLastResult
    }];
    const items = tasks.flatMap(task => window.AutoEditGeneration.collectIssues(task).map(issue => ({ task, issue,
        match: window.AutoEditGeneration.matchIssue(issue, task, records) })));
    if (!items.length) return showToast('请先提供断行文案，或分析有问题的视频任务', 'info');
    document.getElementById('autoedit-generation-matches')?.remove();
    const overlay = document.createElement('div'); overlay.id = 'autoedit-generation-matches';
    overlay.style.cssText = 'position:fixed;inset:0;z-index:1000070;background:rgba(0,0,0,.8);display:grid;place-items:center;padding:20px';
    const panel = document.createElement('section');
    panel.style.cssText = 'width:min(1500px,96vw);max-height:90vh;overflow:auto;background:#171923;padding:20px;border-radius:12px;color:#eee';
    const toolbar = document.createElement('div'); toolbar.style.cssText = 'display:flex;gap:10px;align-items:center;flex-wrap:wrap;position:sticky;top:-20px;background:#171923;padding:12px 0;z-index:1';
    const close = document.createElement('button'); close.className = 'btn btn-secondary'; close.textContent = '关闭'; close.onclick = () => overlay.remove();
    const copyAll = document.createElement('button'); copyAll.className = 'btn btn-primary';
    const sendAllImmediate = document.createElement('button');
    sendAllImmediate.className = 'btn btn-primary';
    sendAllImmediate.style.cssText = 'background:#ea580c;border-color:#ea580c;color:#fff;font-weight:700;';
    sendAllImmediate.textContent = '🚀 全部已匹配发回生成端立即重跑';
    const sendAllMark = document.createElement('button');
    sendAllMark.className = 'btn btn-secondary';
    sendAllMark.style.cssText = 'color:#fde047;border-color:rgba(245,158,11,.45);background:rgba(245,158,11,.12);font-weight:600;';
    sendAllMark.textContent = '⚠️ 全部已匹配发回生成端标待重跑';
    const summary = document.createElement('span'); summary.className = 'hint';
    const results = document.createElement('div'); results.id = 'autoedit-generation-result-table';
    const updateSummary = () => {
        const resolved = items.filter(item => item.match.selected.length).length;
        summary.textContent = `${items.length} 处待匹配文案 · ${resolved} 处已匹配 · ${items.length - resolved} 处待确认/未找到；复制与发回生成端时自动去重`;
        resetCopyButtonFeedback(copyAll);
        copyAll.textContent = '复制全部已匹配的生成资料（前四列）';
        copyAll.disabled = resolved === 0;
        sendAllImmediate.disabled = resolved === 0;
        sendAllMark.disabled = resolved === 0;
        results.replaceChildren();
        const selected = [...new Map(items.flatMap(item => item.match.selected).map(r => [JSON.stringify(r.columns), r])).values()];
        if (selected.length) results.append(createAutoEditGenerationTable(selected, {
            onCopy: record => copyAutoEditGenerationRows([record]),
            related: record => {
                const linked = items.filter(item => item.match.selected.some(r => JSON.stringify(r.columns) === JSON.stringify(record.columns)));
                if (linked.some(item => window.AutoEditGeneration.recordVideoSources(record, item.task, item.issue).length)) return linked;
                const located = window.AutoEditGeneration.associatedVideoTasks(record, autoEditBatchTasks);
                return linked.concat(located.flatMap(item => item.sources.map(source => ({ task: item.task, issue: {
                    source, text: record.text, label: '已有视频 · 请预览核对是否需要重做'
                } }))));
            },
            onReview: (task, record, issue) => openAutoEditGenerationReview(task, record, issue)
        }));
        else results.textContent = '尚无已匹配的结果，请在下方确认对应资料。';
        hydrateAutoEditBatchReviewThumbnails(results);
    };
    copyAll.onclick = () => withCopyButtonFeedback(copyAll, () => copyAutoEditGenerationRows(items.flatMap(item => item.match.selected)));
    sendAllImmediate.onclick = () => sendAutoEditGenerationRowsToHedra(items.flatMap(item => item.match.selected), { autoStart: true }, sendAllImmediate);
    sendAllMark.onclick = () => sendAutoEditGenerationRowsToHedra(items.flatMap(item => item.match.selected), { autoStart: false }, sendAllMark);
    toolbar.append(close, copyAll, sendAllImmediate, sendAllMark, summary); panel.append(toolbar);
    const resultTitle = document.createElement('h3'); resultTitle.textContent = '最终结果 · 复制前四列重新生成';
    panel.append(resultTitle, results);
    const review = document.createElement('details');
    const reviewTitle = document.createElement('summary'); reviewTitle.textContent = '问题文案配对详情 / 调整候选';
    review.open = items.some(item => !item.match.selected.length); review.append(reviewTitle); panel.append(review);
    let initializing = true;
    items.forEach(item => {
        const card = document.createElement('div'); card.style.cssText = 'padding:14px;margin:10px 0;border:1px solid #475569;border-radius:8px';
        const title = document.createElement('strong'); title.textContent = `${item.task.outputName || item.task.name} · ${item.issue.label}`;
        const text = document.createElement('p'); text.style.whiteSpace = 'pre-wrap'; text.textContent = item.issue.text || item.issue.recognized || '没有应说文案，无法自动匹配；可搜索原记录手动确认';
        const source = document.createElement('div'); source.className = 'hint'; source.textContent = item.issue.source?.split(/[/\\]/).pop() || (item.issue.withoutTask ? '未提供对应视频任务（按断行文案配对）' : '缺失片段（按文案匹配）');
        const status = document.createElement('p');
        const actionRow = document.createElement('div');
        actionRow.style.cssText = 'display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:6px 0;';
        const copyOne = document.createElement('button'); copyOne.className = 'btn btn-secondary'; copyOne.textContent = '复制此文案的生成资料（前四列）';
        const sendOneImmediate = document.createElement('button');
        sendOneImmediate.className = 'btn btn-primary';
        sendOneImmediate.style.cssText = 'background:#ea580c;border-color:#ea580c;color:#fff;font-weight:700;';
        sendOneImmediate.textContent = '🚀 发回生成端立即重跑';
        const sendOneMark = document.createElement('button');
        sendOneMark.className = 'btn btn-secondary';
        sendOneMark.textContent = '⚠️ 发回生成端标待重跑';
        actionRow.append(copyOne, sendOneImmediate, sendOneMark);
        const updateCard = () => {
            resetCopyButtonFeedback(copyOne);
            status.textContent = item.match.selected.length ? (item.match.paired ? '已按拆分文案与断行位置配对：' : '已匹配：') + item.match.selected.map(r => r.columns[2]).join('；')
                : item.match.ambiguous ? '多个相近候选，请选择对应生成资料' : '未找到可靠匹配，可在下方搜索并选择原记录';
            copyOne.disabled = !item.match.selected.length;
            sendOneImmediate.disabled = !item.match.selected.length;
            sendOneMark.disabled = !item.match.selected.length;
            if (!initializing) updateSummary();
        };
        copyOne.onclick = () => withCopyButtonFeedback(copyOne, () => copyAutoEditGenerationRows(item.match.selected));
        sendOneImmediate.onclick = () => sendAutoEditGenerationRowsToHedra(item.match.selected, { autoStart: true }, sendOneImmediate);
        sendOneMark.onclick = () => sendAutoEditGenerationRowsToHedra(item.match.selected, { autoStart: false }, sendOneMark);
        const details = document.createElement('details'); details.open = !item.match.selected.length;
        const label = document.createElement('summary'); label.textContent = '查看 / 调整匹配（可勾选多条）';
        const search = document.createElement('input'); search.className = 'input'; search.placeholder = '搜索图片名、生成命名或文案'; search.style.cssText = 'width:100%;margin:10px 0';
        const choices = document.createElement('div'); choices.style.cssText = 'max-height:240px;overflow:auto';
        const renderChoices = () => {
            choices.replaceChildren();
            const q = search.value.trim().toLowerCase();
            const candidates = q ? records.filter(r => `${r.columns[0]} ${r.columns[2]} ${r.text}`.toLowerCase().includes(q))
                : [...new Set([...item.match.selected, ...item.match.candidates.map(c => c.record)])];
            if (!candidates.length) choices.textContent = '没有候选，请输入名称或文案搜索';
            candidates.slice(0, 100).forEach(record => {
                const line = document.createElement('label'); line.style.cssText = 'display:block;padding:8px;border-bottom:1px solid #334155;white-space:pre-wrap;word-break:break-word';
                const check = document.createElement('input'); check.type = 'checkbox'; check.checked = item.match.selected.includes(record);
                check.onchange = () => { item.match.selected = check.checked ? [...item.match.selected, record] : item.match.selected.filter(r => r !== record); updateCard(); };
                line.append(check, document.createTextNode(` ${record.columns[2]}\n图片：${record.columns[0]}\n文案：${record.text || '未提取到文案'}`)); const prompt = document.createElement('details'); const heading = document.createElement('summary'); heading.textContent='生成资料描述词'; const body = document.createElement('div'); body.textContent=record.columns[3]; prompt.append(heading,body); line.append(prompt); choices.append(line);
            });
        };
        search.oninput = renderChoices; details.append(label, search, choices);
        card.append(title, source, text, status, actionRow, details); review.append(card); renderChoices(); updateCard();
    });
    initializing = false;
    overlay.append(panel); document.body.append(overlay); updateSummary();
}
window.showAutoEditGenerationMatches = showAutoEditGenerationMatches;

function buildAutoEditBatchIssuesTable(tasks = []) {
    const list = Array.isArray(tasks) ? tasks : [];
    const rows = [];

    list.forEach(task => {
        const videoName = String(task?.outputName || task?.name || '').trim();
        if (!videoName) return;

        const issueTexts = [];
        // 1. 待确认/缺失文案（优先）
        const missingBlocks = Array.isArray(task?.result?.missing_blocks) ? task.result.missing_blocks : [];
        missingBlocks.forEach(b => {
            if (!b.review_assignment && (b.text || '').trim()) {
                issueTexts.push(b.text.trim());
            }
        });

        // 2. 异常片段文案（如果无 missing_blocks 但有警告/错误片段）
        if (issueTexts.length === 0) {
            const segments = getAutoEditBatchLiveResult(task)?.segments || [];
            segments.forEach(s => {
                if (s?.enabled !== false && !s?.is_hook && s?.review_acknowledged !== true && (s?.status === 'warning' || s?.status === 'error')) {
                    const t = (s.script || s.text || s.script_text || s.expected_text || '').trim();
                    if (t) issueTexts.push(t);
                }
            });
        }

        // 3. 错误信息兜底
        if (issueTexts.length === 0 && (task?.reelsTransferError || task?.message)) {
            const msg = String(task.reelsTransferError || task.message).trim();
            if (msg && msg !== '待分析' && msg !== '分析完成' && msg !== '匹配通过') {
                issueTexts.push(msg);
            }
        }

        if (issueTexts.length === 0) return;

        // 第一列视频名字固定加：换行 + 需修改（单元格内两行）
        const videoCellContent = `${videoName}\n需修改`;
        const escapedVideoCell = `"${videoCellContent.replace(/"/g, '""')}"`;

        // 格式化问题文案：每个文案用英文双引号引起来；若有多段用换行连接
        const quotedParts = issueTexts.map(t => {
            const clean = t.replace(/^"+|"+$/g, '').trim();
            return `"${clean}"`;
        });
        const cellContent = quotedParts.join('\n');

        // 按照 Google Sheets TSV 规范进行单元格转义：外层包引号，内部引号转为 ""
        const escapedCell = `"${cellContent.replace(/"/g, '""')}"`;
        rows.push({
            videoName,
            videoCellContent,
            cellContent,
            tsvLine: `${escapedVideoCell}\t${escapedCell}`
        });
    });

    const escapeHtmlSimple = str => String(str || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    const escapeHtmlWithBreaks = str => escapeHtmlSimple(str).replace(/\r?\n/g, '<br>');
    const htmlRows = rows.map(r => `<tr><td style="white-space:pre-wrap;mso-data-placement:same-cell;">${escapeHtmlWithBreaks(r.videoCellContent)}</td><td style="white-space:pre-wrap;mso-data-placement:same-cell;">${escapeHtmlWithBreaks(r.cellContent)}</td></tr>`).join('');

    return {
        rows,
        tsvText: rows.map(r => r.tsvLine).join('\n'),
        htmlText: rows.length ? `<meta charset="utf-8"><table>${htmlRows}</table>` : ''
    };
}

async function copyAutoEditBatchIssuesTable(filterMode = 'all', triggerBtn = null) {
    if (!autoEditBatchTasks.length) return showToast('当前没有批量任务', 'info');

    const btn = triggerBtn || (typeof event !== 'undefined' ? event?.currentTarget : null);

    let targetTasks = autoEditBatchTasks.filter(task => {
        if (filterMode === 'issues') return autoEditBatchTaskHasIssues(task);
        if (filterMode === 'selected') return task.sendToReels !== false && autoEditBatchTaskHasIssues(task);
        if (filterMode === 'passed') return false;
        return autoEditBatchTaskHasIssues(task);
    });

    if (!targetTasks.length) {
        targetTasks = autoEditBatchTasks.filter(task => autoEditBatchTaskHasIssues(task));
    }

    if (!targetTasks.length) {
        return showToast('太棒了！当前没有发现未通过或有问题的任务', 'info');
    }

    const { rows, tsvText, htmlText } = buildAutoEditBatchIssuesTable(targetTasks);

    if (!rows.length) {
        return showToast('未提取到有效的问题文案', 'warning');
    }

    try {
        let copied = false;
        if (navigator.clipboard?.write && typeof ClipboardItem !== 'undefined' && htmlText) {
            try {
                await navigator.clipboard.write([
                    new ClipboardItem({
                        'text/plain': new Blob([tsvText], { type: 'text/plain' }),
                        'text/html': new Blob([htmlText], { type: 'text/html' })
                    })
                ]);
                copied = true;
            } catch (_) {}
        }
        if (!copied) {
            if (window.electronAPI?.writeClipboardText) {
                await window.electronAPI.writeClipboardText(tsvText);
            } else if (navigator.clipboard?.writeText) {
                await navigator.clipboard.writeText(tsvText);
            }
        }

        // 按钮点击后的即时视觉反馈
        if (btn && btn.textContent) {
            const origText = btn.textContent;
            const origBg = btn.style.background;
            const origColor = btn.style.color;
            const origBorder = btn.style.borderColor;

            btn.textContent = `✅ 已复制 (${rows.length}个视频)`;
            btn.style.background = 'rgba(34, 197, 94, 0.25)';
            btn.style.color = '#86efac';
            btn.style.borderColor = 'rgba(34, 197, 94, 0.6)';

            setTimeout(() => {
                btn.textContent = origText;
                btn.style.background = origBg;
                btn.style.color = origColor;
                btn.style.borderColor = origBorder;
            }, 2200);
        }

        showToast(`✅ 已复制 ${rows.length} 个问题视频及文案，可直接粘贴到 Google 表格`, 'success');
    } catch (error) {
        showToast(`复制失败：${error.message}`, 'error');
    }
}

