function autoEditScriptLines() {
    return (document.getElementById('autoedit-script')?.value || '')
        .split(/\r?\n/)
        .map(s => s.trim())
        .filter(Boolean);
}

function updateAutoEditScriptCount() {
    const el = document.getElementById('autoedit-script-count');
    if (!el) return;
    const lineCount = autoEditScriptLines().length;
    const fileCount = autoEditFiles.length;
    const matchMode = document.getElementById('autoedit-match-mode')?.value || 'script';
    if (matchMode === 'line_per_clip') {
        el.textContent = `${lineCount} 行文案 · ${fileCount} 个片段 · 一行一片段`;
        el.style.color = lineCount && fileCount && lineCount !== fileCount ? '#fbbf24' : '';
    } else {
        el.textContent = `${lineCount} 行字幕文案 · ${fileCount} 个片段 · 自动匹配`;
        el.style.color = '';
    }
}

function autoEditAddFiles(files, { silent = false } = {}) {
    const videoExts = ['.mp4', '.mov', '.mkv', '.avi', '.wmv', '.flv', '.webm', '.m4v'];
    const newFiles = (files || [])
        .filter(f => videoExts.some(ext => String(f.name || '').toLowerCase().endsWith(ext)))
        .map(f => ({ path: f.path || getFileNativePath(f), name: f.name || String(f.path || '') }))
        .filter(f => f.path && !autoEditFiles.some(x => x.path === f.path));

    autoEditFiles.push(...newFiles);
    autoEditFiles.sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true, sensitivity: 'base' }));
    renderAutoEditFiles();
    updateAutoEditScriptCount();
    if (newFiles.length > 0 && !silent) showToast(`已添加 ${newFiles.length} 个视频片段`, 'success');
    return newFiles.length;
}

async function autoEditHandleDrop(event) {
    const capturedPaths = window.electronAPI?.consumeDroppedFilePaths?.() || [];
    const droppedFiles = Array.from(event.dataTransfer?.files || []);
    const fallbackPaths = droppedFiles.map(file => {
        try { return getFileNativePath(file); } catch (_) { return ''; }
    });
    const paths = [...new Set((capturedPaths.length ? capturedPaths : fallbackPaths).filter(Boolean))];
    const videoExt = /\.(mp4|mov|mkv|avi|wmv|flv|webm|m4v)$/i;
    const folders = paths.filter(path => window.electronAPI?.isDirectory?.(path));
    if (folders.length) autoEditCurrentFolder = folders[0];
    const directFiles = droppedFiles.filter(file => videoExt.test(file.name || ''));
    let added = autoEditAddFiles(directFiles, { silent: true });
    let scannedVideos = 0;
    try {
        for (const folder of folders) {
            if (!window.electronAPI?.scanDirectoryRecursive) throw new Error('当前窗口未连接文件夹读取服务，请重启热启动窗口后再试');
            const entries = await window.electronAPI.scanDirectoryRecursive(folder, {
                maxDepth: 30,
                excludedNames: ['审核批次', '_auto_edit', 'backup_clips', '已排除素材', '已排除']
            });
            const videos = filterAutoEditSourceVideos(entries, videoExt);
            scannedVideos += videos.length;
            added += autoEditAddFiles(videos, { silent: true });
        }
        if (folders.length && !scannedVideos && !directFiles.length) return showToast('拖入的文件夹及其子文件夹中没有视频', 'warning');
        if (added) return showToast(`已添加 ${added} 个视频片段${folders.length ? `（来自 ${folders.length} 个文件夹）` : ''}`, 'success');
        showToast('没有新增视频片段（可能已在列表中）', 'info');
    } catch (error) {
        console.error('[AutoEdit] 读取拖入文件夹失败', error);
        showToast(`读取拖入文件夹失败：${error?.message || error}`, 'error');
    }
}

function openAutoEditCurrentFolder() {
    const filePath = autoEditFiles[0]?.path;
    if (!filePath) return showToast('请先添加视频片段', 'info');
    window.electronAPI?.showItemInFolder?.(filePath);
}

async function chooseAutoEditVideoFiles() {
    if (window.electronAPI?.selectFiles) {
        let defaultPath = autoEditCurrentFolder;
        if (!defaultPath && autoEditFiles.length > 0 && autoEditFiles[0]?.path) {
            const p = autoEditFiles[0].path;
            const idx = Math.max(p.lastIndexOf('/'), p.lastIndexOf('\\'));
            if (idx !== -1) defaultPath = p.substring(0, idx);
        }
        const filePaths = await window.electronAPI.selectFiles({
            title: '选择视频片段',
            defaultPath: defaultPath || undefined,
            filters: [{ name: '视频文件', extensions: ['mp4', 'mov', 'mkv', 'avi', 'wmv', 'flv', 'webm', 'm4v'] }]
        });
        if (filePaths && filePaths.length > 0) {
            const files = filePaths.map(p => ({
                path: p,
                name: p.split(/[/\\]/).pop()
            }));
            autoEditAddFiles(files);
            if (!autoEditCurrentFolder && filePaths[0]) {
                const p = filePaths[0];
                const idx = Math.max(p.lastIndexOf('/'), p.lastIndexOf('\\'));
                if (idx !== -1) autoEditCurrentFolder = p.substring(0, idx);
            }
        }
        return;
    }
    document.getElementById('autoedit-video-input')?.click();
}
window.chooseAutoEditVideoFiles = chooseAutoEditVideoFiles;

async function refreshAutoEditCurrentFolder() {
    if (!autoEditCurrentFolder) return showToast('当前列表不是从文件夹拖入；请先拖入一个文件夹后再刷新', 'info');
    if (!window.electronAPI?.scanDirectoryRecursive) return showToast('当前窗口未连接文件夹读取服务，请重启热启动窗口后再试', 'warning');
    try {
        const entries = await window.electronAPI.scanDirectoryRecursive(autoEditCurrentFolder, {
            maxDepth: 30,
            excludedNames: ['审核批次', '_auto_edit', 'backup_clips', '已排除素材', '已排除']
        });
        const videoExt = /\.(mp4|mov|mkv|avi|wmv|flv|webm|m4v)$/i;
        const videos = filterAutoEditSourceVideos(entries, videoExt);
        const added = autoEditAddFiles(videos, { silent: true });
        const task = autoEditActiveBatchIndex >= 0 ? autoEditBatchTasks[autoEditActiveBatchIndex] : null;
        if (task?.folder === autoEditCurrentFolder && added) {
            task.clips = autoEditFiles.map(file => file.path);
            task.exportSignature = '';
        }
        saveAutoEditWorkspaceState();
        showToast(added ? `已刷新当前文件夹，补入 ${added} 个新视频片段` : '当前文件夹已刷新，没有发现新视频片段', 'success');
    } catch (error) {
        showToast(`刷新当前文件夹失败：${error?.message || error}`, 'error');
    }
}
window.openAutoEditCurrentFolder = openAutoEditCurrentFolder;
window.refreshAutoEditCurrentFolder = refreshAutoEditCurrentFolder;

let autoEditClipViewMode = localStorage.getItem('autoedit_clip_view') || 'grid';
let autoEditClipThumbGeneration = 0;
const autoEditClipThumbCache = new Map();
function setAutoEditClipView(mode) {
    autoEditClipViewMode = mode === 'list' ? 'list' : 'grid';
    localStorage.setItem('autoedit_clip_view', autoEditClipViewMode);
    renderAutoEditFiles();
}
window.setAutoEditClipView = setAutoEditClipView;
function playAutoEditSourceClip(index) {
    const file = autoEditFiles[index];
    if (file?.path) window.playVideoClip(file.path, 0, 0);
}
window.playAutoEditSourceClip = playAutoEditSourceClip;
async function loadAutoEditClipThumbnails(list, generation) {
    const images = Array.from(list.querySelectorAll('[data-autoedit-thumb]'));
    const files = autoEditFiles.slice();
    let cursor = 0;
    const worker = async () => {
        while (cursor < images.length && generation === autoEditClipThumbGeneration) {
            const image = images[cursor++];
            const file = files[Number(image.dataset.autoeditThumb)];
            if (!file) continue;
            const segment = autoEditLastResult?.segments?.find(item => item.source === file.path);
            const key = segment?.source_identity || file.path;
            let thumbnail = autoEditClipThumbCache.get(key);
            if (!thumbnail) {
                try { thumbnail = await batchCutGenThumb(file.path); } catch (_) {}
                if (thumbnail) autoEditClipThumbCache.set(key, thumbnail);
            }
            if (generation !== autoEditClipThumbGeneration || !image.isConnected) continue;
            if (thumbnail) { image.src = thumbnail; image.style.display = 'block'; image.nextElementSibling.style.display = 'none'; }
            else image.nextElementSibling.textContent = '暂无缩略图 · 点击播放';
        }
    };
    await Promise.all([worker(), worker()]);
}

function renderAutoEditFiles() {
    const list = document.getElementById('autoedit-file-list');
    if (!list) return;
    const generation = ++autoEditClipThumbGeneration;
    const grid = autoEditClipViewMode === 'grid';
    list.style.display = grid ? 'grid' : 'block';
    list.style.gridTemplateColumns = 'repeat(auto-fill,minmax(210px,1fr))';
    list.style.gap = '10px';
    list.style.maxHeight = grid ? '560px' : '280px';
    const viewSelect = document.getElementById('autoedit-clip-view');
    if (viewSelect) viewSelect.value = autoEditClipViewMode;
    if (autoEditFiles.length === 0) {
        list.innerHTML = '<p class="hint">请先选择视频片段。</p>';
        return;
    }

    const startBtn = document.getElementById('autoedit-start-btn');
    const isProcessing = startBtn && startBtn.disabled;

    list.innerHTML = autoEditFiles.map((file, i) => {
        const statusVal = file.status || '';
        let statusHtml = '';
        if (statusVal === 'transcribing') {
            statusHtml = `<span style="color: var(--accent); font-weight: 600; padding: 2px 6px; background: rgba(102,126,234,0.1); border-radius: 3px; font-size: 11px;">⏳ 转录中</span>`;
        } else if (statusVal === 'cached') {
            statusHtml = `<span style="color: #4dabf7; font-weight: 600; padding: 2px 6px; background: rgba(77,171,247,0.1); border-radius: 3px; font-size: 11px;">✅ 已转录</span>`;
        } else if (statusVal === 'transcribed') {
            statusHtml = `<span style="color: #4dabf7; font-weight: 600; padding: 2px 6px; background: rgba(77,171,247,0.1); border-radius: 3px; font-size: 11px;">✅ 已转录</span>`;
        } else if (statusVal === 'failed') {
            statusHtml = `<span style="color: #ff6b6b; font-weight: 600; padding: 2px 6px; background: rgba(255,107,107,0.1); border-radius: 3px; font-size: 11px;" title="${escapeHtml(file.error || '转录失败')}">❌ 失败</span>`;
        } else if (statusVal === 'empty') {
            statusHtml = `<span style="color:#f59f00;font-weight:600;padding:2px 6px;background:rgba(245,159,0,.1);border-radius:3px;font-size:11px;" title="${escapeHtml(file.error || '识别服务未返回文字结果，请点击右侧重新识别')}">⚠️ 未获得识别结果</span>`;
        } else if (statusVal === 'unmatched') {
            statusHtml = `<span style="color: #f76707; font-weight: 600; padding: 2px 6px; background: rgba(247,103,7,0.1); border-radius: 3px; font-size: 11px;" title="${escapeHtml(file.error || '未匹配到任何断行文案')}">⚠️ 未匹配到文案</span>`;
        } else if (statusVal === 'excluded_duplicate') {
            statusHtml = `<span style="color:#c084fc;font-weight:700;padding:2px 6px;background:rgba(168,85,247,.16);border-radius:3px;font-size:11px;">✓ 重复片段已排除</span>`;
        } else if (statusVal === 'excluded_review') {
            statusHtml = `<span style="color:#adb5bd;font-weight:600;padding:2px 6px;background:rgba(148,163,184,.12);border-radius:3px;font-size:11px;">✓ 审核中已排除</span>`;
        } else if (statusVal === 'pending') {
            statusHtml = `<span style="color: var(--text-muted); padding: 2px 6px; background: rgba(255,255,255,0.03); border-radius: 3px; font-size: 11px;">排队中</span>`;
        } else if (statusVal === 'discarded') {
            statusHtml = `<span style="color: #f08c00; font-weight: 600; padding: 2px 6px; background: rgba(240,140,0,0.15); border-radius: 3px; font-size: 11px;">❌ 未采用</span>`;
        }

        const selectSubtitleBtn = `<button class="btn btn-secondary" onclick="selectAutoEditManualSubtitle(${i})" style="padding: 2px 6px; font-size: 11px;" title="手动指定此视频的 .srt/.json/.txt 字幕文件">🔗 字幕</button>`;

        const actionHtml = isProcessing
            ? ''
            : `
                <div style="display: flex; gap: 4px; align-items: center;">
                    ${selectSubtitleBtn}
                    ${file.status ? `<button class="btn btn-secondary" onclick="clearAutoEditFileCache(${i})" style="padding: 2px 6px; font-size: 11px;" title="清除此视频的转录缓存，下次运行将重新识别">🔄 重新识别</button>` : ''}
                    <button class="btn btn-secondary" onclick="removeAutoEditFile(${i})" style="padding: 2px 6px; font-size: 11px;">移除</button>
                </div>
            `;

        const orderHtml = (file.outputIndex && file.outputIndex < 9999)
            ? `<span style="color: #228be6; font-weight: bold; font-size: 11px; padding: 2px 6px; border: 1px solid rgba(34,139,230,0.3); border-radius: 3px; background: rgba(34,139,230,0.05); margin-right: 6px;">🎬 播放顺序 #${file.outputIndex}</span>`
            : '';

        const subtextHtml = file.manualSubtitlePath
            ? `<div style="font-size: 10px; color: #4dabf7; margin-top: 2px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="手动指定字幕: ${escapeHtml(file.manualSubtitlePath)}">📄 字幕: ${escapeHtml(file.manualSubtitlePath.split(/[/\\]/).pop())} <span style="cursor: pointer; color: #ff6b6b; font-weight: bold;" onclick="clearAutoEditManualSubtitle(${i}, event)">[清除]</span></div>`
            : '';

        const thumbnailHtml = `<button type="button" onclick="playAutoEditSourceClip(${i})" title="播放原视频" style="position:relative;width:100%;height:${grid ? '150px' : '50px'};padding:0;border:0;border-radius:5px;background:#111;color:#aaa;overflow:hidden;cursor:pointer;"><img data-autoedit-thumb="${i}" alt="视频片段 ${i + 1}" style="display:none;width:100%;height:100%;object-fit:contain;"><span style="font-size:11px;">正在生成缩略图…</span></button>`;
        if (grid) return `<div style="display:flex;flex-direction:column;gap:7px;padding:9px;background:var(--bg-secondary,#222);border:1px solid var(--border-color,#444);border-radius:7px;min-width:0;">
            ${thumbnailHtml}<div style="display:flex;justify-content:space-between;align-items:center;gap:4px;"><strong style="color:var(--accent);">#${i + 1}</strong>${statusHtml}</div>
            <div title="${escapeHtml(file.path)}" style="font-size:12px;overflow-wrap:anywhere;">${escapeHtml(file.name)}</div>
            <div style="font-size:11px;">${orderHtml}${subtextHtml}</div><div style="margin-top:auto;">${actionHtml}</div></div>`;
        return `
            <div style="display: grid; grid-template-columns: 38px 70px 1fr auto auto; gap: 8px; align-items: center; padding: 6px 8px; border-bottom: 1px solid var(--border-color); font-size: 12px;">
                <strong style="color: var(--accent);">#${i + 1}</strong>
                ${thumbnailHtml}
                <div style="overflow: hidden; display: flex; flex-direction: column;">
                    <span title="${escapeHtml(file.path)}" style="overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">
                        ${orderHtml}${escapeHtml(file.name)}
                    </span>
                    ${subtextHtml}
                </div>
                ${statusHtml}
                ${actionHtml}
            </div>
        `;
    }).join('');
    loadAutoEditClipThumbnails(list, generation);
}

async function selectAutoEditManualSubtitle(index) {
    if (index < 0 || index >= autoEditFiles.length) return;
    try {
        if (window.electronAPI?.selectFiles) {
            const result = await window.electronAPI.selectFiles({
                multiple: false,
                title: '选择字幕文件',
                filters: [
                    { name: '字幕/文本文件 (*.srt, *.json, *.txt)', extensions: ['srt', 'json', 'txt'] }
                ]
            });
            if (result && result.length > 0) {
                autoEditFiles[index].manualSubtitlePath = result[0];
                autoEditFiles[index].status = '';
                autoEditFiles[index].error = null;
                renderAutoEditFiles();
                showToast(`已选择字幕文件: ${result[0].split(/[/\\]/).pop()}`, 'success');
            }
        }
    } catch (e) {
        showToast('选择字幕文件失败: ' + e.message, 'error');
    }
}

function clearAutoEditManualSubtitle(index, event) {
    if (event) event.stopPropagation();
    if (index < 0 || index >= autoEditFiles.length) return;
    autoEditFiles[index].manualSubtitlePath = null;
    autoEditFiles[index].status = '';
    autoEditFiles[index].error = null;
    renderAutoEditFiles();
    showToast('已清除手动指定的字幕', 'info');
}

// 审核详情中的快捷入口：API 识别有误时，可直接为当前原片段指定人工校正的 SRT。
// 选择后立刻重新分析整套素材，使新的词级时间线、匹配结果和切点保持一致。
async function selectAutoEditReviewSrt(button) {
    const source = getAutoEditReviewRowSource(button);
    const index = autoEditFiles.findIndex(file => file.path === source);
    if (index < 0) return showToast('未找到当前片段，无法替换字幕', 'error');
    try {
        const result = await window.electronAPI?.selectFiles?.({
            multiple: false,
            title: '为当前片段选择手动校正的 SRT 字幕',
            filters: [{ name: 'SRT 字幕文件 (*.srt)', extensions: ['srt'] }]
        });
        if (!result?.[0]) return;
        const srtPath = result[0];
        autoEditFiles[index].manualSubtitlePath = srtPath;
        autoEditFiles[index].status = '';
        autoEditFiles[index].error = null;
        const batchTask = autoEditActiveBatchIndex >= 0 ? autoEditBatchTasks[autoEditActiveBatchIndex] : null;
        if (batchTask) {
            persistAutoEditBatchReview();
            flushAutoEditProjectReview();
            batchTask.manualSubtitleMap = batchTask.manualSubtitleMap || {};
            batchTask.manualSubtitleMap[source] = srtPath;
        }
        renderAutoEditFiles();
        showToast(`已替换为 ${srtPath.split(/[/\\]/).pop()}，正在重新分析…`, 'info', 3500);
        await startAutoEditByScript(false, {
            analysisOnly: true,
            preserveReviewedResults: true,
            replacementSources: [source],
            scriptTextOverride: batchTask ? batchTask.script : undefined,
            outputDirOverride: batchTask ? getAutoEditBatchAnalysisDir(batchTask) : undefined,
            requestSettingsOverride: batchTask?.settings || undefined,
        });
    } catch (error) {
        showToast(`选择 SRT 失败: ${error.message}`, 'error');
    }
}

window.selectAutoEditManualSubtitle = selectAutoEditManualSubtitle;
