    const placeholders = [...document.querySelectorAll('.autoedit-missing-placeholder:not([data-assigned="true"])')];
    if (!placeholders.length) return showToast('没有待确认文案；可直接编辑当前片段上方的目标文案', 'info', 6000);
    const overlay = document.createElement('div');
    overlay.style.cssText = 'position:fixed;inset:0;z-index:300000;background:rgba(0,0,0,.75);display:flex;align-items:center;justify-content:center;';
    const box = document.createElement('div');
    box.style.cssText = 'width:min(760px,90vw);max-height:80vh;overflow:auto;background:#1c1d2b;color:white;padding:20px;border-radius:10px;';
    const title = document.createElement('h3'); title.textContent = `选择归到片段 #${row.dataset.sourceIndex} 的待确认文案`;
    const hint = document.createElement('p'); hint.textContent = '请选择整段待确认文案。归属后请试听，并核对入点、出点和字幕。';
    const cancel = document.createElement('button'); cancel.className = 'btn btn-secondary'; cancel.textContent = '取消'; cancel.onclick = () => overlay.remove();
    box.append(title,hint);
